const undoStack=[],redoStack=[];
const clone=v=>JSON.parse(JSON.stringify(v));
function commit(label,fn){undoStack.push(clone(state));redoStack.length=0;fn();state.history.push(label);state.changes++;state.saved=false;state.operation=null;render();toast(label+' applied. Undo is available.');}
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),3300);}
function go(project,workspace){const p=projects[project];state.project=project;state.workspace=workspace||p.workspace;state.selected=p.selected;state.view=state.workspace==='room'?'plan':state.workspace==='sketch'?'sketch':state.workspace==='drawings'?'sheet':'3d';state.aiDraft=false;state.aiApplied=false;state.section=false;state.flat=false;state.explode=0;state.measure=false;state.saved=true;state.changes=0;document.getElementById('toast').classList.remove('visible');undoStack.length=0;redoStack.length=0;state.operation=null;state.inspector='properties';state.manufacturing=null;state.hidden=[];state.placed=[];state.history=project==='makerspace'?['Room outline','Wall height','Entry door','South window','Assembly bench','Laser cutter','Service clearance']:project==='table'?['Master sketch','Top layers','Side profile','Tube frame','Miter cuts','Mounting holes','Glue joint']:project==='case'?['Carcass sketch','Panels','Finger joints','Drawer rail','Transferred holes','Printed drawer','Slider joint']:['PCB import','Master sketch','Front panel','Bends','Plywood cheeks','MX key guide','Screen hinge'];state.modal=null;render();}
const button=(action,label,i='',cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${i?icon(i):''}${label}</button>`;
const toolButton=(action,label,i)=>`<button type="button" class="tool ${state.operation?.kind===action?'active':''}" data-action="${action}">${icon(i)}${label}</button>`;
let fieldScope='inspector';
const field=(name,value,key,unit='mm',linked=false)=>`<div class="field"><label for="f-${fieldScope}-${key}">${name}</label><div class="field-input">${linked?icon('link'):''}<input id="f-${fieldScope}-${key}" data-field="${key}" type="number" value="${value}" step="${unit==='mm'?1:.1}" min="0" aria-label="${name}"><span>${unit}</span></div></div>`;
const selectField=(label,key,values,current)=>`<div class="field"><label for="f-${fieldScope}-${key}">${label}</label><select id="f-${fieldScope}-${key}" data-select="${key}">${values.map(v=>`<option ${v===current?'selected':''}>${v}</option>`).join('')}</select></div>`;
const check=(key,label,value=true)=>`<label class="check-line"><input type="checkbox" data-toggle="${key}" ${value?'checked':''}>${label}</label>`;
const notice=(text,type='',i='info')=>`<div class="notice ${type}">${icon(i)}<div>${text}</div></div>`;
function render(){const p=projects[state.project];app.innerHTML=`<main class="app" aria-label="MultiCAD desktop prototype">
<header class="topbar"><div class="brand"><span class="brand-mark"><span></span></span>MULTICAD</div><span class="rule"></span><button class="project-button" data-action="projects">${p.name}${icon('down')}</button><span class="pill ${state.saved?'':'orange'}">${state.saved?'Saved':'Unsaved'}</span><div class="row" style="margin-left:10px"><button class="icon-btn" data-action="save" aria-label="Save project" title="Save prototype state · ⌘S">${icon('save')}</button><button class="icon-btn" data-action="undo" aria-label="Undo" title="Undo · ⌘Z" ${undoStack.length?'':'disabled'}>${icon('undo')}</button><button class="icon-btn" data-action="redo" aria-label="Redo" title="Redo · ⇧⌘Z" ${redoStack.length?'':'disabled'}>${icon('redo')}</button></div><button class="top-search" data-action="commands">${icon('search')}<span>Find a tool…</span><span class="key">⌘ K</span></button><button class="sync-button" data-action="sync">${icon('cloud')}<span>Local project</span></button><button class="ai-top" data-action="ai">${icon('spark')}<span>AI & connections</span><span class="dot"></span></button><button class="icon-btn" data-action="settings" aria-label="Settings" title="Application settings">${icon('settings')}</button><div class="avatar">TK</div></header>
<nav class="workspaces" aria-label="Workspace">${spaces.map(([id,i,label])=>`<button type="button" class="workspace ${state.workspace===id?'active':''}" data-space="${id}" aria-current="${state.workspace===id?'page':'false'}">${icon(i)}${label}</button>`).join('')}<button class="library-button" data-action="library">${icon('library')}Library</button></nav>
<div class="toolbar" aria-label="${state.workspace} tools">${toolsets[state.workspace].map(([i,label,a])=>toolButton(a,label,i)).join('')}<span class="spacer"></span><span class="rule"></span>${toolButton('export','Export','download')}</div>
<div class="main">${tree()}<section class="center" aria-label="Design canvas"><div class="viewport"><div class="view-head"><div><h1 class="view-title">${viewTitle()}</h1><div class="view-sub">${viewSub()}</div></div><div class="view-mode">${(state.workspace==='drawings'?['Sheet','Model']:state.workspace==='sketch'?['Sketch','3D']:['Plan','3D']).map(v=>`<button data-view="${v.toLowerCase()}" class="${isView(v)?'active':''}">${v}</button>`).join('')}</div></div><div class="scene" id="scene">${scene()}</div>${state.workspace==='sketch'||state.workspace==='drawings'?'':`<button class="view-cube" data-action="cycle-view" title="Change view">${state.view==='plan'?'TOP':'ISO'}</button>`}<div class="view-tools"><button class="icon-btn" data-action="zoom-in" aria-label="Zoom in" title="Zoom in">${icon('plus')}</button><button class="icon-btn" data-action="zoom-out" aria-label="Zoom out" title="Zoom out">${icon('minus')}</button><button class="icon-btn" data-action="fit-view" aria-label="Fit view" title="Fit all">${icon('fit')}</button><button class="icon-btn ${state.grid?'active':''}" data-action="toggle-grid" aria-label="Toggle grid" title="Grid">${icon('grid')}</button><button class="icon-btn ${state.section?'active':''}" data-action="section" aria-label="Section view" title="Section view">${icon('section')}</button></div><div class="axis"><span class="axis-line"></span><span class="axis-line y"></span><span class="axis-line z"></span><span class="axis-label" style="left:37px;bottom:15px">X</span><span class="axis-label" style="left:0;bottom:31px">Y</span><span class="axis-label" style="left:13px;bottom:43px">Z</span></div><div class="scene-hint">${state.workspace==='room'?'Drag equipment to explore the layout · Select to edit':state.workspace==='sketch'?'Select profiles · Dimensions stay linked · Esc cancels an operation':state.workspace==='assembly'?'Adjust the position control to inspect fit and clearance':state.workspace==='drawings'?'Select a view to adjust its scale · Add dimensions and notes':'Drag to orbit · Select to inspect · Scroll to zoom'}</div>${state.operation?`<div class="operation-preview">${icon('check')}<div><strong>Preview · ${esc(state.operation.label)}</strong><small>Review targets and parameters, then apply.</small></div></div>`:`<div class="selection-chip">${icon(state.workspace==='sketch'?'sketch':'cube')}<span>${state.workspace==='sketch'?`${state.profiles.length} closed profiles selected`:esc(state.selected)}</span><span class="pill">${state.workspace==='sketch'?'Constrained':state.workspace==='drawings'?'Associative view':'Selected'}</span></div>`}${state.manufacturing?manufacturing():''}</div>${timeline()}</section>${inspector()}</div>
<footer class="statusbar"><button data-action="health">${icon(state.sketchIssue?'alert':'check')}<span>${state.sketchIssue?'1 reference needs attention':'Model up to date'}</span></button><span class="optional-mobile">${state.workspace==='sketch'?'Fully constrained · 0 degrees of freedom':'mm · '+(state.workspace==='room'?'1:50':'1:1')}</span><span class="optional-status">${state.selected?1:0} selected</span><span class="spacer"></span><span class="prototype-tag">UX PROTOTYPE · SAMPLE DATA · NO CAD COMPUTATION</span><button class="help-link" data-action="tour">${icon('help')}Explore workflows</button></footer></main>`;renderModal();bindCanvas();if(!state.grid){app.querySelector('.viewport').classList.add('no-grid');} }
function isView(v){if(v==='Sheet')return state.view!=='model';if(v==='Model')return state.view==='model';if(v==='Sketch')return state.view!=='3d';return v.toLowerCase()===state.view;}
function viewTitle(){if(state.workspace==='sketch')return 'Master sketch';if(state.workspace==='drawings')return 'Manufacturing drawing';if(state.workspace==='sheet'&&state.flat)return 'Front panel · Flat pattern';if(state.workspace==='weld')return 'Tube frame · Weldment';if(state.workspace==='wood')return state.project==='case'?'Carcass · Panel joinery':'Laminated top · Wood assembly';if(state.workspace==='print')return 'Drawer insert · Print preparation';if(state.workspace==='assembly')return state.project==='console'?'Display hinge · Assembly':'Tool case · Assembly';return projects[state.project].name;}
function viewSub(){return state.workspace==='sketch'?'XY plane · Shared by 3 features':state.workspace==='drawings'?`Sheet 01 of 03 · A3 landscape · Scale ${state.drawingScale}`:state.workspace==='sheet'&&state.flat?'5052 aluminium · 2 mm · 4 bends · Cut geometry at 1:1':projects[state.project].subtitle;}
function tree(){const p=projects[state.project],parts=[...p.parts,...state.placed];const sketchMode=state.workspace==='sketch';return `<aside class="tree-panel" aria-label="Project structure"><div class="panel-heading"><strong>Project</strong><button class="icon-btn small-ico" data-action="new-part" aria-label="Add to project">${icon('plus')}</button></div><label class="tree-search">${icon('search')}<input placeholder="Filter objects" data-tree-search aria-label="Filter project objects"></label><div class="tree-root">${icon('down')}${icon('folder')} ${p.name}</div><div class="tree-group"><div class="tree-group-label">${icon('down','small-ico')} ${sketchMode?'Sketches & construction':'Parts & assemblies'}</div>${(sketchMode?['Master sketch','Panel cutouts','Mounting references']:parts).map((name,i)=>`<button class="tree-item ${state.selected===name||sketchMode&&i===0?'selected':''} ${state.hidden.includes(name)?'faded':''}" data-part="${esc(name)}">${icon(sketchMode?'sketch':/frame|hinge|carcass|rails/i.test(name)?'assembly':'cube')}<span>${esc(name)}</span>${i===1&&state.project==='case'?'<span class="mini-count">×2</span>':''}<span class="eye" role="button" tabindex="0" aria-label="Toggle visibility of ${esc(name)}" data-eye="${esc(name)}">${icon(state.hidden.includes(name)?'hide':'eye')}</span></button>`).join('')}</div><div class="tree-group"><div class="tree-group-label">${icon('down','small-ico')} Reference geometry</div><button class="tree-item" data-action="new-sketch">${icon('sketch')}Master sketch<span class="mini-count">↗ 3</span></button><button class="tree-item" data-action="planes">${icon('plane')}Origin & planes</button>${state.project==='console'?`<button class="tree-item" data-action="pcb">${icon('link')}control-board.kicad_pcb</button>`:''}</div><div class="tree-group"><div class="tree-group-label">${icon('down','small-ico')} Documentation</div><button class="tree-item" data-space="drawings">${icon('drawing')}Manufacturing drawings<span class="mini-count">3</span></button><button class="tree-item" data-action="manufacturing">${icon('list')}Parts & schedules</button></div><div class="tree-bottom"><div class="eyebrow">Reusable by design</div><p>Turn a part or this whole assembly into a parametric symbol.</p>${button('create-symbol','Create symbol','library','small')}</div><div class="tree-status"><span class="dot"></span>Local project · Revision ${p.version}</div></aside>`;}
function timeline(){return `<div class="timeline"><div class="timeline-top"><span>Design history <span style="margin-left:7px;color:#a0a794">${state.history.length} features</span></span><button data-action="parameters">${icon('sliders')}<span>Parameters</span></button></div><div class="history-items"><button class="icon-btn small-ico" data-action="history-start" aria-label="Show first feature">${icon('undo')}</button>${state.history.map((name,i)=>`${i?'<span class="history-link"></span>':''}<button class="history-item ${i===state.history.length-1?'current':''}" data-history="${i}" title="${esc(name)}" aria-label="Edit ${esc(name)}">${icon(/sketch|outline|path/i.test(name)?'sketch':/hole|cut/i.test(name)?'hole':/joint|weld/i.test(name)?'joint':/layer|laminat|panel/i.test(name)?'layers':'extrude')}</button>`).join('')}<span class="history-end"></span><button class="icon-btn small-ico" data-action="features" aria-label="Add feature">${icon('plus')}</button></div></div>`;}
function inspector(){let content=state.inspector==='ai'?aiInspector():state.operation?operationInspector():state.inspector==='relationships'?relationshipsInspector():properties();let actions=state.inspector==='ai'?(state.aiDraft?button('ai-apply','Apply changes','check','primary')+button('ai-discard','Discard','','small'):button('ai-send','Preview changes','spark','primary')):state.operation?button('cancel-op','Cancel','','')+button('apply-op','Apply','check','primary'):button('edit-selection','Edit feature','sliders','small')+button('export','Export','download','small');return `<aside class="inspector" aria-label="Properties and operations"><nav class="inspector-tabs"><button data-inspector="properties" class="${state.inspector==='properties'?'active':''}">Properties</button><button data-inspector="relationships" class="${state.inspector==='relationships'?'active':''}">References</button><button data-inspector="ai" class="${state.inspector==='ai'?'active':''}">${icon('spark')}AI</button></nav><div class="inspector-content">${content}</div><div class="inspector-actions">${actions}</div></aside>`;}
function properties(){const w=state.workspace,p=projects[state.project];if(w==='room')return `<div class="object-type">${icon('cube')}Equipment · Dynamic symbol</div><h2 class="object-name">${esc(state.selected)}</h2><span class="pill green">Library definition · v1.2</span><p class="inspector-description">Footprint and service access stay visible while you position the equipment.</p><div class="section-label">Dimensions <span>Exposed</span></div>${field('Width',1900,'equipmentWidth')}${field('Depth',1100,'equipmentDepth')}${field('Height',1050,'equipmentHeight')}<div class="section-label">Placement</div>${field('X position',Math.round((state.room.laser.x-170)*10),'roomX')}${field('Y position',Math.round((state.room.laser.y-110)*10),'roomY')}${field('Rotation',0,'rotation','°')}<div class="section-label">Clearances</div>${check('clearance','Show service envelope',state.clearance)}${field('Front access',600,'frontAccess')}${notice(`Front access: <strong>${roomGap()} mm</strong><br>${roomGap()>=600?'Fits with service clearance.':'Below the 600 mm service requirement.'}`,roomGap()>=600?'':'warning',roomGap()>=600?'check':'alert')}<button class="list-action" data-action="symbol-update">Definition updates ${icon('refresh')}</button><button class="list-action" data-action="companion">Open site companion ${icon('phone')}</button>`;
if(w==='sketch')return `<div class="object-type">${icon('sketch')}Sketch · XY plane</div><h2 class="object-name">Master sketch</h2><span class="pill green">Fully constrained</span><p class="inspector-description">One sketch, multiple independent parts. Select the closed regions you want to use.</p>${field('Overall width',state.sketchWidth,'sketchWidth', 'mm',true)}${field('Overall height',state.sketchHeight,'sketchHeight','mm',true)}<div class="section-label">Profiles <span>${state.profiles.length} selected</span></div>${[0,1,2].map(i=>check('profile-'+i,['Main plate','Mounting bracket','Center cutout'][i],state.profiles.includes(i))).join('')}<div class="section-label">Constraints</div>${['Horizontal × 6','Coincident × 8','Equal length × 2','Symmetric × 1','Driving dimensions × 4'].map(x=>`<div class="check-line">${icon('lock')}${x}</div>`).join('')}${button('constraints','Manage constraints','magnet','small')}${notice('Changes here update Front panel, Mounting bracket, and Panel cutouts.','','link')}`;
if(w==='wood')return `<div class="object-type">${icon('wood')}Panel assembly · 4 parts</div><h2 class="object-name">${state.project==='case'?'Plywood carcass':'Laminated top'}</h2><span class="pill green">Manufacturing part</span><div class="section-label">Panel definition</div>${field('Thickness',state.woodThickness,'woodThickness')}${field('Length',1600,'panelLength')}${field('Width',800,'panelWidth')}<div class="material"><span class="swatch"></span><span>Birch plywood<small>18 mm · B/BB · Sheet stock</small></span></div><div class="section-label">Construction</div>${selectField('Layers','layers',['2 × 18 mm','3 × 12 mm','Single panel'],'2 × 18 mm')}${selectField('Grain direction','grain',['Along length','Along width'],'Along length')}${check('edgeBand','Edge banding · Front edge',false)}<div class="section-label">Connections</div><button class="list-action" data-action="joint">${icon('joint')} ${state.joint==='finger'?'Finger':state.joint==='miter'?'Miter':'Butt'} joint · Side panel ${icon('chevron')}</button><button class="list-action" data-action="laminate">${icon('layers')} Glued lamination ${icon('chevron')}</button>${notice('Panel names, grain direction, and finished dimensions carry into the cut list.','','list')}`;
if(w==='sheet')return `<div class="object-type">${icon('sheet')}Sheet metal · Folded & flat</div><h2 class="object-name">Front panel</h2><span class="pill green">Flat pattern linked</span><div class="section-label">Material & bends</div>${selectField('Material','sheetMaterial',['Aluminium · 5052','Steel · S235','Stainless · 304'],'Aluminium · 5052')}${field('Thickness',state.sheetThickness,'sheetThickness')}${field('Inside radius',state.bendRadius,'bendRadius')}${field('K-factor',.42,'kFactor','')}${field('Flange height',24,'flangeHeight')}<div class="segmented"><button data-action="folded" class="${!state.flat?'active':''}">Folded model</button><button data-action="flat" class="${state.flat?'active':''}">Flat pattern</button></div><div class="section-label">Bend definitions</div>${['Front flange · 90° up','Left flange · 90° up','Right flange · 90° up','Rear flange · 90° up'].map((v,i)=>`<button class="list-action" data-action="bend">B${i+1} &nbsp; ${v}${icon('chevron')}</button>`).join('')}${notice('Bend allowance is a material/process input. Review it before releasing a flat pattern.','warning')}<button class="list-action" data-action="bends">Bend schedule ${icon('list')}</button>`;
if(w==='weld')return `<div class="object-type">${icon('weld')}Weldment · 12 members</div><h2 class="object-name">Tube frame</h2><span class="pill green">Member identities preserved</span><div class="section-label">Stock profile</div>${selectField('Section','stockProfile',['SHS 30 × 30 × 2','SHS 40 × 40 × 2','CHS Ø 32 × 2','RHS 40 × 20 × 2'],'SHS 30 × 30 × 2')}${selectField('Material','stockMaterial',['Steel · S235','Stainless · 304','Aluminium'],'Steel · S235')}${field('Frame width',1500,'frameWidth')}${field('Frame depth',700,'frameDepth')}${field('Frame height',700,'frameHeight')}<div class="section-label">Selected end treatment</div>${selectField('Cut type','endCut',['45° miter','Square cut','Cope to member','Notch'],'45° miter')}${field('Weld gap',.8,'weldGap')}<div class="section-label">Weld plan</div>${['Tack opposite corners','Weld short-side pairs','Weld long-side pairs','Attach mounting plates'].map((s,i)=>`<div class="step-row"><span class="step-num">${i+1}</span><span>${s}</span></div>`).join('')}<button class="list-action" data-action="sequence">Edit weld order ${icon('chevron')}</button><button class="list-action" data-action="fixture">Fixture table layout ${icon('grid')}</button>`;
if(w==='print')return `<div class="object-type">${icon('print')}FDM design preparation</div><h2 class="object-name">Drawer insert</h2><span class="pill">PETG · Removable aids</span><div class="section-label">Print orientation</div>${selectField('Build face','buildFace',['Bottom face','Back face','Selected plane'],'Bottom face')}${field('Wall thickness',2.4,'wallThickness')}${field('Fit clearance',.3,'printClearance')}<div class="section-label">Design aids <span>${state.supports}</span></div><button class="list-action" data-action="support">${icon('pin')}Breakaway tabs · ${state.supports}${icon('plus')}</button><button class="list-action" data-action="bridge">${icon('joint')}Thin sacrificial bridge${icon('plus')}</button>${field('Tab thickness',.4,'tabThickness')}${field('Contact width',1.2,'tabContact')}${check('showAids','Show removable aids',true)}${notice('Aids remain separate parts. Choose whether to include them in your 3MF or STL export.','','layers')}<button class="list-action" data-action="section">Inspect wall section ${icon('section')}</button>`;
if(w==='assembly')return `<div class="object-type">${icon('assembly')}Assembly relationship</div><h2 class="object-name">${state.project==='console'?'Display hinge':'Drawer extension'}</h2><span class="pill green">${state.project==='console'?'Revolute':'Slider'} · 1 free movement</span><p class="inspector-description">Inspect useful positions and check clearances without a physics simulation.</p><div class="section-label">Position</div><div class="range-label"><span>${state.project==='console'?'Opening angle':'Extension'}</span><strong class="mono" id="motion-value">${state.project==='console'?state.hinge+'°':state.drawers+' mm'}</strong></div><input class="range" type="range" min="0" max="${state.project==='console'?110:400}" value="${state.project==='console'?state.hinge:state.drawers}" data-range="${state.project==='console'?'hinge':'drawers'}" aria-label="${state.project==='console'?'Hinge opening angle':'Drawer extension'}"><div class="range-limits"><span>Closed · 0</span><span>${state.project==='console'?'110°':'400 mm'} · Limit</span></div><div class="segmented"><button data-pose="0">Closed</button><button data-pose="${state.project==='console'?55:200}">Halfway</button><button data-pose="${state.project==='console'?100:380}">Extended</button></div><div class="section-label">Clearance check</div><div id="motion-notice">${motionNotice()}</div>${button('interference','Check current position','check','small')}${button('sweep','Check movement range','play','small', 'style="margin-top:8px"')}<div class="section-label">Assembly display</div><div class="range-label"><span>Explode distance</span><span class="mono">${state.explode} mm</span></div><input class="range" type="range" min="0" max="120" value="${state.explode}" data-range="explode" aria-label="Explode distance"><button class="list-action" data-action="relationship">Edit relationship ${icon('link')}</button><button class="list-action" data-action="holes">Transfer rail mounting holes ${icon('hole')}</button>`;
if(w==='drawings')return `<div class="object-type">${icon('drawing')}Drawing sheet · Associative</div><h2 class="object-name">Part fabrication</h2><span class="pill green">Matches current revision</span><div class="section-label">Sheet setup</div>${selectField('Paper','paper',['A3 landscape','A4 landscape','A4 portrait'],'A3 landscape')}${selectField('Projection','projection',['First angle','Third angle'],'First angle')}${selectField('View scale','drawingScale',['1:1','1:2','1:5','1:10'],'1:5')}<div class="section-label">Placed views</div>${['Front · 1:5','Top · 1:5','Right · 1:5','Section A–A · 1:2','Isometric · 1:8'].map(x=>`<button class="list-action" data-action="add-view">${icon(x.startsWith('Section')?'section':'drawing')}${x}${icon('chevron')}</button>`).join('')}<div class="section-label">Annotation</div><textarea class="full-input" rows="3" data-note aria-label="Drawing note">${esc(state.drawingNote)}</textarea>${check('showDims','Show associative dimensions',state.dimensions)}<button class="list-action" data-action="drawing-dimension">Add dimension ${icon('ruler')}</button><button class="list-action" data-action="manufacturing">Insert parts or bend table ${icon('list')}</button>`;
return `<div class="object-type">${icon('cube')}Part · ${esc(p.materials[p.parts.indexOf(state.selected)]||'Custom component')}</div><h2 class="object-name">${esc(state.selected)}</h2><span class="pill green">Parametric solid</span><div class="section-label">Driving dimensions</div>${field('Width',state.sketchWidth===120?480:state.sketchWidth,'sketchWidth','mm',true)}${field('Depth',280,'modelDepth','mm',true)}${field('Height',state.depth,'depth')}${field('Wall / stock',2,'stockThickness')}<div class="section-label">Material</div><div class="material"><span class="swatch" style="background:#a5b2a8"></span><span>Aluminium · 5052<small>Appearance and manufacturing material</small></span></div><div class="section-label">Feature relationships</div><button class="list-action" data-space="sketch">${icon('sketch')}Master sketch${icon('link')}</button><button class="list-action" data-action="pcb">${icon('hole')}PCB mounting holes${icon('link')}</button><button class="list-action" data-action="edit-selection">${icon('extrude')}Extrusion · ${state.depth} mm${icon('chevron')}</button><div class="section-label">Part actions</div><button class="list-action" data-action="new-sketch">Sketch on selected face ${icon('sketch')}</button><button class="list-action" data-action="boolean">Combine / subtract ${icon('union')}</button><button class="list-action" data-action="create-symbol">Create library symbol ${icon('library')}</button><button class="list-action" data-action="appearance">Rendering properties ${icon('cube')}</button>`;}
function operationInspector(){const op=state.operation;const common=`<div class="operation-title">${icon(op.icon||'sliders')}${esc(op.label)}</div><p class="inspector-description">${op.description||'Edit the parameters below and review the highlighted geometry before applying.'}</p>`;if(op.kind==='extrude')return common+`<div class="section-label">Source profiles</div><div class="target-box">${icon('sketch')}Master sketch · ${state.profiles.length||2} profiles</div>${selectField('Result','extrudeResult',['New independent parts','Add to selected parts','Subtract from selected parts','Intersect with selected parts'],op.result||'New independent parts')}${field('Distance',state.depth,'depth')}${selectField('Direction','direction',['One side','Symmetric','Two sides'],'One side')}${selectField('Extent','extent',['Distance','Through all','Up to face'],'Distance')}${check('keepSketch','Keep sketch reusable',true)}${notice('Each selected region becomes an independent part. Editing the shared sketch updates all dependent features.','','layers')}<div class="section-label">Preview result</div><div class="target-box">${icon('cube')}Front panel · New part</div><div class="target-box">${icon('cube')}Mounting bracket · New part</div>`;
if(op.kind==='joint')return common+`<div class="section-label">Connected panels</div><div class="target-box">${icon('wood')}Top panel · Edge 2</div><div class="target-box">${icon('wood')}Side panel · Edge 1</div><div class="section-label">Joint type</div><div class="option-grid">${[['finger','Finger joint'],['miter','Miter'],['butt-a','Butt · Top through'],['butt-b','Butt · Side through']].map(([id,label])=>`<button data-joint="${id}" class="${state.joint===id?'active':''}">${icon(id==='miter'?'rotate':'joint')}${label}</button>`).join('')}</div>${state.joint==='finger'?field('Finger count',state.fingers,'fingers','')+field('Fit clearance',.15,'jointClearance'):state.joint==='miter'?field('Miter angle',45,'miterAngle','°'):field('Panel overlap',state.woodThickness,'overlap')}${check('bothSides','Generate cuts in both panels',true)}${notice('Both panels derive their cuts from this joint. Thickness changes update both sides.','','link')}`;
if(op.kind==='boolean')return common+`<div class="section-label">Operation</div><div class="option-grid">${[['Union','union'],['Subtract','cut'],['Intersect','layers'],['Split','section']].map(([v,i])=>`<button class="${(op.result||'Subtract')===v?'active':''}" data-boolean="${v}">${icon(i)}${v}</button>`).join('')}</div><div class="section-label">Target parts</div><div class="target-box">${icon('cube')}${esc(state.selected)}</div><div class="section-label">Tool geometry</div><div class="target-box">${icon('cube')}Mounting hole pattern</div>${check('keepTools','Keep tool bodies',true)}${notice('Targets are explicit. Neighboring parts remain independent.','','info')}`;
if(op.kind==='holes'||op.kind==='pcb')return common+`<div class="section-label">Source</div><div class="target-box">${icon('link')}${state.project==='case'?'Drawer rail · 4 mounting holes':'control-board.kicad_pcb · J1, J2, H1–H4'}</div><div class="section-label">Receiving parts</div>${check('targetPanel','Front panel',true)}${check('targetWood','Plywood side / carcass',true)}${check('targetDrawer','Drawer body',state.project==='case')}${selectField('Geometry','holeMode',['Mounting holes','Component cutouts','Board outline'],'Mounting holes')}${field('Radial clearance',.2,'holeClearance')}${field('Cut depth',state.depth,'depth')}${check('associative','Keep linked to source',true)}${notice('Source updates propose matching hole changes. Missing references are flagged for repair.','','link')}`;
if(op.kind==='relationship')return common+`<div class="section-label">Components</div><div class="target-box">${icon('cube')}Drawer rail · Fixed member</div><div class="target-box">${icon('cube')}Upper drawer · Moving member</div>${selectField('Relationship','jointType',['Fixed','Slider','Revolute','Cylindrical','Planar'],state.jointType)}${field('Minimum',0,'motionMin')}${field('Maximum',400,'motionMax')}${check('linkedMovement','Link to companion rail',true)}${notice('Use the position control to inspect a pose, then check for interference.','','sliders')}`;
if(['wall','door','window','level'].includes(op.kind))return common+`${selectField('Place on','wallTarget',['North wall','East wall','South wall','West wall'],'South wall')}${field(op.kind==='wall'?'Wall length':'Width',op.kind==='wall'?6200:900,'wallLength')}${field('Height',op.kind==='window'?1200:state.wallHeight,'wallHeight')}${field(op.kind==='window'?'Sill height':'Thickness',op.kind==='window'?900:200,'wallThickness')}${op.kind==='door'?selectField('Hinge side','doorHinge',['Left','Right'],'Left')+selectField('Opening','doorOpening',['Inward','Outward'],'Inward'):''}${notice('Dimensions drive both the plan representation and the 3D model.','','link')}`;
if(op.kind==='bend')return common+`<div class="target-box">${icon('sheet')}Front panel · Selected edge</div>${field('Flange length',24,'flangeHeight')}${field('Bend angle',90,'bendAngle','°')}${field('Inside radius',state.bendRadius,'bendRadius')}${selectField('Position','bendPosition',['Material inside','Material outside','Centered'],'Material inside')}${selectField('Relief','bendRelief',['Rectangular','Round','Tear'],'Round')}${check('flatUpdate','Update flat pattern',true)}`;
if(['support','bridge'].includes(op.kind))return common+`<div class="target-box">${icon('print')}Drawer insert · Selected edge</div>${field('Thickness',.4,'tabThickness')}${field('Contact width',1.2,'tabContact')}${field('Spacing',30,'tabSpacing')}${check('separateAid','Keep as removable aid',true)}${notice('This is editable design geometry. Slicing remains in your external slicer.','','print')}`;
if(op.kind==='features')return common+`<div class="section-label">Shape tools</div>${['Fillet / chamfer','Shell / thickness','Sweep along path','Loft between profiles','Draft angle','Mirror / pattern'].map(v=>`<button class="list-action" data-feature="${v}">${icon('cube')}${v}${icon('chevron')}</button>`).join('')}`;
return common+`<div class="section-label">Selection</div><div class="target-box">${icon('cube')}${esc(state.selected)}</div>${field(op.kind==='revolve'?'Angle':'Distance',op.kind==='revolve'?360:state.depth,'depth',op.kind==='revolve'?'°':'mm')}${selectField('Reference','featureReference',['Selected geometry','Origin plane','Construction plane'],'Selected geometry')}${check('linkedFeature','Keep parametric relationship',true)}${notice('Preview changes are not committed until you choose Apply.','','eye')}`;}
function relationshipsInspector(){return `<div class="object-type">${icon('link')}Design dependencies</div><h2 class="object-name">References</h2><p class="inspector-description">See what drives this part and what will update when it changes.</p><div class="section-label">Driven by</div><button class="list-action" data-space="sketch">${icon('sketch')}Master sketch${icon('chevron')}</button><button class="list-action" data-action="parameters">${icon('sliders')}Project dimensions${icon('chevron')}</button><button class="list-action" data-action="pcb">${icon('link')}Mounting references${icon('chevron')}</button><div class="section-label">Used by</div><button class="list-action" data-space="drawings">${icon('drawing')}Part fabrication · Sheet 01${icon('chevron')}</button><button class="list-action" data-action="manufacturing">${icon('list')}Cut list & BOM${icon('chevron')}</button><button class="list-action" data-space="assembly">${icon('assembly')}Main assembly${icon('chevron')}</button>${state.sketchIssue?notice('The face used by Mounting sketch was removed. Choose a replacement reference.','danger','alert'):notice('All source references resolve.','','check')}${button('repair','Inspect reference repair','link','small')}<div class="section-label">Library definition</div><div class="field"><span>Installed version</span><span class="pill">v1.2</span></div><button class="list-action" data-action="symbol-update">Review update to v1.3 ${icon('refresh')}</button>`;}
function aiInspector(){return `<div class="object-type">${icon('spark')}AI & MCP connections</div><h2 class="object-name">Design together</h2><span class="pill green">${state.mcp?'Local access enabled':'Local access off'}</span><p class="inspector-description">${state.aiDraft||state.aiApplied?'Review this sample transaction and its affected geometry.':'Connected assistants use the same editable operations as you. Review proposed changes before applying.'}</p><button class="list-action" data-action="connections">Connection permissions ${icon('settings')}</button>${state.aiDraft||state.aiApplied?'':'<div class="ai-message">Try a sample request to explore the review flow.</div>'}${state.aiDraft||state.aiApplied?`<div class="ai-message user">${esc(state.aiPrompt||'Add four mounting holes to the selected panel, linked to the PCB.')}</div><div class="section-label">${state.aiApplied?'Applied as one undoable change':'Proposed changes · 3 steps'}</div>${(state.aiPrompt.includes('cabinet')?['Read cabinet and drawer parameters','Set exposed cabinet width to 700 mm','Update linked panels, drawers, and cut list']:state.aiPrompt.includes('drawing')?['Read selected manufacturing part','Add front, top, isometric, and section views','Place dimensions and revision title block']:['Read selected part and PCB references','Project 4 mounting-hole centers','Create linked Ø 3.4 mm through holes']).map((v,i)=>`<div class="ai-command">${icon(state.aiApplied?'check':i===0?'eye':'plus')}${v}</div>`).join('')}${notice(state.aiApplied?'Changes are in the design history. Undo restores the previous state.':'Preview highlights the affected panel. No committed geometry has changed.','','eye')}`:''}<textarea class="ai-composer" id="ai-prompt" placeholder="Describe a change to this project…" aria-label="Design request">${esc(state.aiPrompt)}</textarea><div class="ai-examples"><button data-ai-example="Add four mounting holes to the selected panel, linked to the PCB.">Transfer PCB holes</button><button data-ai-example="Make the cabinet 700 mm wide and update its drawers.">Resize cabinet</button><button data-ai-example="Create a dimensioned manufacturing drawing for the selected part.">Create drawing</button></div><div class="section-label">Available capabilities</div><p class="inspector-description">Inspect · Sketch · Model · Assemble · Validate · Draw · Export</p>`;}
function motionNotice(){const problem=state.project==='console'?state.hinge>82:state.drawers>335;return notice(problem?'<strong>Interference detected</strong><br>'+ (state.project==='console'?'Display hinge meets the rear key row.':'Drawer handle enters the adjacent door envelope.'):'<strong>No interference at this position</strong><br>Minimum clearance: '+(state.project==='console'?Math.max(1,Math.round(28-state.hinge*.25)):Math.max(1,Math.round(38-state.drawers*.08)))+' mm.',problem?'warning':'',problem?'alert':'check');}
function roomGap(){return Math.max(0,Math.round((state.room.bench.y-(state.room.laser.y+110))*10));}

// Schematic vector scenes are illustrative UX data, not CAD output.
const svgOpen=(label,extra='')=>`<svg viewBox="0 0 1000 650" role="img" aria-label="${label}" ${extra}><defs><pattern id="grain" width="19" height="9" patternUnits="userSpaceOnUse"><path d="M0 2Q9 -1 19 3M0 7Q11 4 19 8" fill="none" stroke="#967c4f" stroke-width=".5" opacity=".23"/></pattern><pattern id="hatch" width="8" height="8" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><path d="M0 0v8" stroke="#a5b19a" stroke-width="1"/></pattern><filter id="ground-shadow"><feGaussianBlur stdDeviation="13"/></filter></defs>`;
function dimension(x1,y1,x2,y2,text,vertical=false){return `<g><path class="dim-line" d="M${x1} ${y1}L${x2} ${y2}"/><path class="dim-line" d="${vertical?`M${x1-4} ${y1+4}l8-8M${x2-4} ${y2+4}l8-8`:`M${x1-4} ${y1+4}l8-8M${x2-4} ${y2+4}l8-8`}"/><text class="dim" x="${(x1+x2)/2+(vertical?-8:0)}" y="${(y1+y2)/2+(vertical?0:-8)}" text-anchor="${vertical?'end':'middle'}" ${vertical?`transform="rotate(-90 ${(x1+x2)/2-8} ${(y1+y2)/2})"`:''}>${text}</text></g>`;}
function roomScene(){const l=state.room.laser,b=state.room.bench;let clear=roomGap();return svgOpen('Top-down makerspace layout with draggable laser cutter, workbench, doors, windows and service clearance')+`<g transform="translate(0 5)"><rect x="173" y="114" width="620" height="410" fill="#e5e9da" stroke="none"/><path class="wall" data-part="Room walls" d="M163 104H803V534H603V514H783V124H183V514H483V534H163Z"/><path class="opening" d="M473 524h130"/><path d="M483 524V415a110 110 0 0 1 110 110" fill="none" stroke="#a8b69b" stroke-width="1.2"/><path d="M483 524V414" stroke="#77886d" stroke-width="3"/><text class="tiny" x="535" y="548" text-anchor="middle">Entry · 1,100</text><rect x="803" y="199" width="8" height="130" fill="#a3bfbc"/><path d="M783 199h20M783 329h20" stroke="#617e76"/><text class="tiny" transform="translate(826 263) rotate(90)" text-anchor="middle">Window · Sill 900</text><rect x="209" y="143" width="59" height="205" rx="2" fill="#d0c6a5" stroke="#9ca68e"/><path d="M209 183h59M209 224h59M209 265h59M209 306h59" stroke="#b0b394"/><text class="tiny" transform="translate(245 245) rotate(-90)" text-anchor="middle">STORAGE SHELVES</text><rect data-part="Assembly bench" x="${b.x}" y="${b.y}" width="380" height="45" rx="2" fill="#cab88f" stroke="#9d9e7f"/><rect pointer-events="none" x="${b.x}" y="${b.y}" width="380" height="45" fill="url(#grain)"/><text class="tiny" x="${b.x+190}" y="${b.y+26}" text-anchor="middle">ASSEMBLY BENCH</text>${state.clearance?`<rect class="clearance" x="${l.x-25}" y="${l.y-25}" width="240" height="195" rx="5"/><text x="${l.x+95}" y="${l.y+155}" text-anchor="middle" fill="${clear<600?'#b25a37':'#839372'}" font-size="10">Service access · ${clear} mm available</text>`:''}<g data-part="Laser cutter" data-drag="laser"><rect x="${l.x}" y="${l.y}" width="190" height="110" rx="4" fill="#c8d4cc" stroke="${state.selected==='Laser cutter'?'#b95f3d':'#8c9f90'}" stroke-width="${state.selected==='Laser cutter'?2:1}"/><rect x="${l.x+13}" y="${l.y+13}" width="130" height="65" rx="3" fill="#b3c4b8" stroke="#8b9f8e"/><path d="M${l.x+22} ${l.y+32}h111 M${l.x+22} ${l.y+42}h111 M${l.x+22} ${l.y+52}h111 M${l.x+22} ${l.y+62}h111" stroke="#8ca78e" stroke-width=".7"/><rect x="${l.x+154}" y="${l.y+16}" width="23" height="31" rx="2" fill="#7f9382"/><circle cx="${l.x+165}" cy="${l.y+61}" r="4" fill="#b95f3d"/><text class="label" x="${l.x+95}" y="${l.y+98}" text-anchor="middle">LASER CUTTER</text><circle opacity="${state.selected==='Laser cutter'?1:0}" cx="${l.x}" cy="${l.y}" r="3" fill="#f9f6ed" stroke="#b95f3d"/><circle opacity="${state.selected==='Laser cutter'?1:0}" cx="${l.x+190}" cy="${l.y+110}" r="3" fill="#f9f6ed" stroke="#b95f3d"/></g><text class="tiny" x="339" y="365" text-anchor="middle">CIRCULATION</text><path d="M329 410v-62m-5 6 5-6 5 6" stroke="#a8b39b" fill="none"/><text class="label" x="483" y="165" text-anchor="middle" style="letter-spacing:1.5px;font-size:13px">MAKERSPACE</text><text class="tiny" x="483" y="184" text-anchor="middle">25.4 m² · Finished height ${state.wallHeight.toLocaleString('en')} mm</text>${state.dimensions?dimension(173,78,793,78,'6,200')+dimension(131,114,131,524,'4,100',true):''}${false?dimension(l.x+190,l.y+55,783,l.y+55,Math.round((783-l.x-190)*10)+' mm'):''}${state.placed.map((name,i)=>`<g data-part="${esc(name)}"><rect x="${320+i*22}" y="${205+i*15}" width="80" height="55" fill="#d5c098" stroke="#aa845a"/><text class="tiny" x="${360+i*22}" y="${235+i*15}" text-anchor="middle">${esc(name.split(' ·')[0])}</text></g>`).join('')}</g></svg>`;}
let yaw=-.62;
function projectPoint(x,y,z,scale=1){if(state.view==='plan')return [500+x*scale,330+y*scale];const c=Math.cos(yaw),s=Math.sin(yaw),rx=x*c-y*s,ry=x*s+y*c;return [500+rx*scale,450+ry*.43*scale-z*.88*scale];}
function boxFaces(x,y,z,w,d,h,color,name='',scale=1,angle=0){const palette={wood:['#cfb685','#b39a6b','#ddc99f'],metal:['#aebbb1','#82978a','#c4d0c4'],dark:['#6e8072','#4e6456','#8c9e8b'],print:['#b8c3a3','#8c9d78','#d0d8bd'],pcb:['#64856c','#49684e','#809d7a'],orange:['#dba276','#b9734b','#efbd96'],glass:['#8daba2','#6b8d82','#b8ccc1']};const p=palette[color]||palette.metal;let points=[[x,y,z],[x+w,y,z],[x+w,y+d,z],[x,y+d,z],[x,y,z+h],[x+w,y,z+h],[x+w,y+d,z+h],[x,y+d,z+h]];if(angle)points=points.map(([a,b,c])=>[a,y+(b-y)*Math.cos(angle)-(c-z)*Math.sin(angle),z+(b-y)*Math.sin(angle)+(c-z)*Math.cos(angle)]);const projected=points.map(v=>projectPoint(...v,scale));return [[0,1,5,4],[1,2,6,5],[4,5,6,7]].map((ix,i)=>({depth:ix.reduce((n,j)=>n+points[j][0]*Math.sin(yaw)+points[j][1]*Math.cos(yaw)+points[j][2]*.02,0)/4,markup:`<polygon points="${ix.map(j=>projected[j].join(',')).join(' ')}" fill="${p[i]}" stroke="${state.selected===name||state.operation&&/panel|mount|top/i.test(name)?'#b95f3d':'#647563'}" stroke-width="${state.selected===name?'1.8':'.7'}" stroke-linejoin="round" ${name?`data-part="${esc(name)}" data-face="${i+1}"`:''}/>${color==='wood'&&i===2?`<polygon points="${ix.map(j=>projected[j].join(',')).join(' ')}" fill="url(#grain)" pointer-events="none"/>`:''}`}));}
function isoScene(project=state.project,small=false){let boxes=[],s=1,annotation='';const add=(...args)=>boxes.push(...boxFaces(...args));const ex=state.explode*.25;const printMode=state.workspace==='print';const weldMode=state.workspace==='weld';const woodMode=state.workspace==='wood';const room=project==='makerspace';
if(room){s=.8;add(-330,-220,-9,660,440,9,'wood','Room floor',s);add(-340,-230,0,10,460,190,'metal','West wall',s);add(-330,-230,0,660,10,190,'metal','North wall',s);add(-270,-175,0,55,270,140,'wood','Storage shelves',s);add(-130,100,0,380,60,90,'wood','Assembly bench',s);add(0,-90,0,190,110,105,'metal','Laser cutter',s);add(12,-78,105,130,85,7,'glass','Laser cutter',s);}
else if(printMode&&project==='case'){s=1.65;add(-150,-100,0,300,200,7,'print','Drawer insert',s);add(-150,-100,7,7,200,65,'print','Drawer insert',s);add(143,-100,7,7,200,65,'print','Drawer insert',s);add(-143,-100,7,286,7,65,'print','Drawer insert',s);add(-143,93,7,286,7,65,'print','Drawer insert',s);for(let i=0;i<3;i++)add(-75+i*75,-93,7,4,186,47,'print','Divider',s);for(let i=0;i<state.supports;i++)add(-155+i*110,101,0,35,15,2,'orange','Breakaway aid',s);annotation='PETG · 0.3 mm assembly clearance';}
else if(project==='case'){s=.85;const pull=state.drawers*.5;add(-180,-120,0,360,240,15,'wood','Plywood carcass',s);add(-180,-120,15,15,240,350,'wood','Plywood carcass',s);add(165,-120,15,15,240,350,'wood','Plywood carcass',s);add(-165,-120,350+ex,330,240,15,'wood','Plywood carcass',s);add(-165,-120,15,330,12,335,'wood','Plywood carcass',s);for(let k=0;k<2;k++){const z=65+k*150,dy=k?pull:pull*.12;add(-145, -90+dy, z,290,200,6,'print',k?'Upper drawer':'Lower drawer',s);add(-145,-90+dy,z+6,7,200,90,'print',k?'Upper drawer':'Lower drawer',s);add(138,-90+dy,z+6,7,200,90,'print',k?'Upper drawer':'Lower drawer',s);add(-138,103+dy,z+6,276,7,90,'print',k?'Upper drawer':'Lower drawer',s);add(-135,110+dy,z+6,270,12,90,'wood',k?'Upper drawer':'Lower drawer',s);add(-55,123+dy,z+40,110,10,12,'dark','Drawer handle',s);add(-160,-90,z+35,8,200,10,'metal','Drawer rail · left',s);add(152,-90,z+35,8,200,10,'metal','Drawer rail · right',s);}for(const x of [-150,130])for(const y of [-95,85])add(x,y,-28,24,24,28,'dark','Castors',s);}
else if(project==='table'){s=.63;const tops=true;for(const x of [-315,285])for(const y of [-135,105])add(x,y,0,25,25,290,'dark','Welded frame',s);add(-315,-135,270,625,25,25,'dark','Welded frame',s);add(-315,105,270,625,25,25,'dark','Welded frame',s);add(-315,-110,270,25,215,25,'dark','Welded frame',s);add(285,-110,270,25,215,25,'dark','Welded frame',s);add(-315,-135,45,625,25,20,'dark','Welded frame',s);add(-315,105,45,625,25,20,'dark','Welded frame',s);if(tops){add(-350,-175,300+ex,700,350,state.woodThickness*.6,'wood','Laminated top',s);add(-350,-175,315+ex*2,700,350,state.woodThickness*.6,'wood','Laminated top',s);if(!state.section)add(-350,-175,331+ex*3,18,350,80,'wood','Angled side panel',s);}if(weldMode){for(const [x,y]of[[-302,-120],[298,-120],[-302,117],[298,117]]){const pt=projectPoint(x,y,295,s);annotation+=`<circle cx="${pt[0]}" cy="${pt[1]}" r="5" fill="#c7834b" stroke="#9d6038"/><text x="${pt[0]+10}" y="${pt[1]-7}" font-size="10" fill="#9d6038">W${x<0?1:2}${y<0?'A':'B'}</text>`;}}}
else {s=1.2;add(-220,-110,0,440,220,12,'wood','Base plate',s);add(-235-ex,-110,12,15,220,120,'wood','Left cheek',s);add(220+ex,-110,12,15,220,120,'wood','Right cheek',s);if(!state.section)add(-220,-110,12,440,210,12,'metal','Front panel',s);add(-220,-110,24,440,8,37,'metal','Rear flange',s);add(-220,92,24,440,8,22,'metal','Front flange',s);add(-196,-80,27+ex,315,135,3,'pcb','Main PCB',s);add(-178,-62,35+ex*1.6,270,109,7,'print','MX key guide',s);for(let row=0;row<3;row++)for(let col=0;col<8;col++)add(-171+col*33,-55+row*33,44+ex*2,25,25,10,'dark','MX key guide',s);for(let i=0;i<4;i++)add(138,-70+i*35,25,28,24,10,'dark','Encoder',s);if(state.workspace==='assembly'||state.hinge>0){add(-170,-118,65,320,13,150,'dark','Display & hinge',s,-state.hinge*Math.PI/180);add(-158,-115,75,296,4,123,'glass','Display & hinge',s,-state.hinge*Math.PI/180);}}
state.placed.forEach((name,i)=>{if(name==='Extruded plate')add(-130,-70,170+ex,120,80,state.depth,'metal',name,s);else if(name==='Mounting bracket'){add(30,-70,170+ex,80,16,state.depth,'metal',name,s);add(30,-70,170+ex,16,65,state.depth,'metal',name,s);}else add(-100+i*90,140,10,70,55,90,'wood',name,s);});const visible=boxes.filter(b=>!state.hidden.some(n=>b.markup.includes(`data-part="${esc(n)}"`)));visible.sort((a,b)=>a.depth-b.depth);let out=svgOpen('Illustrative isometric '+projects[project].name+' assembly with selectable components');out+=`<ellipse cx="505" cy="503" rx="270" ry="47" fill="#b2bd9f" opacity=".15" filter="url(#ground-shadow)"/>`+visible.map(b=>b.markup).join('');if((state.aiDraft&&!state.aiPrompt.includes('cabinet')&&!state.aiPrompt.includes('drawing'))||state.operation?.kind==='holes')out+=holeMarkers();if(state.section)out+=`<path d="M300 530 730 350 730 130 300 310Z" fill="#dba06f" fill-opacity=".12" stroke="#bc7045" stroke-dasharray="5 4"/><text x="714" y="122" fill="#a86e40" font-size="11">A–A</text>`;if(state.workspace==='weld')out+=annotation;else if(annotation)out+=`<text x="500" y="565" text-anchor="middle" class="tiny">${annotation}</text>`;if(state.workspace==='wood'&&state.operation?.kind==='joint')out+=jointDetail();if(state.dimensions&&!small&&!room)out+=dimension(240,565,760,565,project==='table'||weldMode?'1,600':project==='case'?'620':'480');return out+'</svg>';}
function holeMarkers(){return [[-185,-75],[185,-75],[-185,65],[185,65]].map(([x,y],i)=>{const p=projectPoint(x,y,30,1.2);return `<g><ellipse cx="${p[0]}" cy="${p[1]}" rx="6" ry="3" fill="#f7f5e8" stroke="#bd6942" stroke-width="1.5"/><path d="M${p[0]-10} ${p[1]}h20M${p[0]} ${p[1]-7}v14" stroke="#bd6942" stroke-width=".8"/><text x="${p[0]+12}" y="${p[1]-8}" fill="#a5633b" font-size="10">H${i+1}</text></g>`;}).join('');}
function jointDetail(){let fingers='';for(let i=0;i<state.fingers;i++){const x=72+i*120/state.fingers;fingers+=`<rect x="${x}" y="190" width="${60/state.fingers}" height="18" fill="#c5ab7b" stroke="#997e51" stroke-width=".8"/>`;}return `<g><rect x="49" y="126" width="180" height="126" rx="7" class="annotation"/><text x="65" y="150" class="tiny">JOINT DETAIL</text>${state.joint==='finger'?`<path d="M69 174h140v17H69zM69 209h140v17H69z" fill="#d6bf92" stroke="#a38c5e"/>${fingers}`:state.joint==='miter'?`<path d="M72 178h126l-23 23H72zM198 178v48h-23v-25z" fill="#d6bf92" stroke="#a38c5e"/>`:`<path d="M72 178h126v20H72zM${state.joint==='butt-a'?178:198} 198v29h-20v-29z" fill="#d6bf92" stroke="#a38c5e"/>`}<text x="65" y="241" class="tiny">${state.joint==='finger'?'0.15 mm fit clearance':state.joint==='miter'?'45° mating faces':'Choose the through panel'}</text></g>`;}
function sketchScene(){return svgOpen('Parametric sketch with three selectable profiles and dimensional constraints')+`<g transform="translate(0 5)"><path class="construction" d="M140 350h690M350 100v440"/><path d="M350 350h50 M350 350v-50" stroke="#bd7961" stroke-width="1.1"/><circle cx="350" cy="350" r="4" fill="#fafbf5" stroke="#a56e54"/><text class="tiny" x="365" y="371">ORIGIN</text><rect class="profile ${state.profiles.includes(0)?'picked':''}" data-profile="0" x="350" y="190" width="${state.sketchWidth*2.8}" height="160" rx="9" fill="#dce7d5" stroke="#4e8064" stroke-width="1.8"/><path class="profile ${state.profiles.includes(1)?'picked':''}" data-profile="1" d="M350 395h230v62H410v56h-60Z" fill="#dce7d5" stroke="#4e8064" stroke-width="1.8"/><rect class="profile ${state.profiles.includes(2)?'picked':''}" data-profile="2" x="445" y="235" width="135" height="66" rx="10" fill="#eef1e7" stroke="#4e8064" stroke-width="1.8"/><circle cx="380" cy="219" r="7" fill="#f7f8f0" stroke="#4e8064" stroke-width="1.7"/><circle cx="655" cy="219" r="7" fill="#f7f8f0" stroke="#4e8064" stroke-width="1.7"/><circle cx="380" cy="321" r="7" fill="#f7f8f0" stroke="#4e8064" stroke-width="1.7"/><circle cx="655" cy="321" r="7" fill="#f7f8f0" stroke="#4e8064" stroke-width="1.7"/><text class="tiny" x="520" y="334" text-anchor="middle">MAIN PLATE</text><text class="tiny" x="468" y="433" text-anchor="middle">MOUNTING BRACKET</text>${dimension(350,152,350+state.sketchWidth*2.8,152,`${state.sketchWidth} mm · width`)}${dimension(307,190,307,350,`${state.sketchHeight} mm`,true)}${dimension(445,280,580,280,'48 mm')}<g fill="#fafbf5" stroke="#6c9070" stroke-width="1.1"><rect x="489" y="181" width="15" height="15" rx="3"/><rect x="341" y="255" width="15" height="15" rx="3"/><rect x="630" y="340" width="15" height="15" rx="3"/></g><g fill="#5e8465" font-size="11"><text x="493" y="192">H</text><text x="345" y="266">V</text><text x="634" y="351">H</text></g><path d="M380 219 419 185" stroke="#8da17f" stroke-width=".8"/><text class="dim" x="420" y="181">4 × Ø 3.4</text><rect x="100" y="145" width="150" height="77" rx="6" class="annotation"/><text class="label" x="115" y="170">Shared sketch</text><text class="tiny" x="115" y="190">3 closed profiles</text><text class="tiny" x="115" y="206">Select one or more regions</text></g></svg>`;}
function flatScene(){return svgOpen('Unfolded sheet-metal front panel with cutouts and bend lines')+`<g><path d="M280 180h440v32h35v230h-35v32H280v-32h-35V212h35Z" fill="#dbe1d3" stroke="#71836a" stroke-width="1.5"/><path d="M280 212h440M280 442h440M280 212v230M720 212v230" stroke="#bd7954" stroke-width="1.2" stroke-dasharray="7 5" fill="none"/>${Array.from({length:3},(_,r)=>Array.from({length:8},(_,c)=>`<rect x="${310+c*39}" y="${251+r*43}" width="26" height="26" rx="1" fill="#f0f3e8" stroke="#84967a" stroke-width=".8"/>`).join('')).join('')}${[0,1,2].map(i=>`<circle cx="683" cy="${263+i*51}" r="10" fill="#f0f3e8" stroke="#84967a"/>`).join('')}${[[300,232],[700,232],[300,422],[700,422]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="3" fill="#f0f3e8" stroke="#84967a"/>`).join('')}<text class="dim" x="500" y="203" text-anchor="middle">B1 · 90° UP · R ${state.bendRadius}</text><text class="dim" x="500" y="460" text-anchor="middle">B4 · 90° UP · R ${state.bendRadius}</text><text class="dim" transform="translate(265 327) rotate(-90)" text-anchor="middle">B2 · 90° UP</text><text class="dim" transform="translate(740 327) rotate(90)" text-anchor="middle">B3 · 90° UP</text>${dimension(245,140,755,140,'528.4 mm · developed width')}${dimension(795,180,795,474,'328.4 mm',true)}<path d="M770 410h45l40 36" class="dim-line"/><text class="tiny" x="805" y="464">Corner relief</text><g transform="translate(325 526)"><path d="M0 0h35" stroke="#71836a"/><text x="45" y="4" class="tiny">Cut</text><path d="M110 0h35" stroke="#bd7954" stroke-dasharray="6 4"/><text x="155" y="4" class="tiny">Bend</text><text x="250" y="4" class="tiny">Scale 1:1 on export</text></g></g></svg>`;}
function roomDrawingScene(){return svgOpen('Dimensioned room plan with equipment, openings, level notes and revision title block')+`<rect x="130" y="100" width="740" height="440" fill="#fffef8" stroke="#d5d9cc"/><rect x="150" y="118" width="700" height="402" fill="none" stroke="#8a9481" stroke-width=".8"/><text x="170" y="145" class="label">GROUND FLOOR · EQUIPMENT PLAN</text>${roomScene().replace('<svg ','<svg x="140" y="135" width="540" height="345" ')}<text x="680" y="185" class="tiny">ROOM SCHEDULE</text><text x="680" y="208" class="label">Area · 25.4 m²</text><text x="680" y="229" class="label">Clear height · ${state.wallHeight} mm</text><text x="680" y="250" class="label">Finished floor · ±0.00</text><text x="680" y="295" class="tiny">OPENINGS</text><text x="680" y="318" class="label">D01 · 1,100 × 2,100</text><text x="680" y="339" class="label">W01 · Sill 900</text><text x="170" y="466" class="tiny">Maintain equipment service envelopes. Verify site dimensions.</text><path d="M150 490h700M600 490v30" stroke="#8a9481" stroke-width=".7"/><text x="170" y="509" class="label">MAKERSPACE / GROUND FLOOR</text><text x="615" y="509" class="tiny">REV 04 · A3 · 1:50 · SHEET 01 / 03</text></svg>`;}
function drawingScene(){if(state.project==='makerspace')return roomDrawingScene();return svgOpen('A3 manufacturing drawing with orthographic, section and isometric views and editable dimensions')+`<g class="drawing-paper"><rect x="130" y="100" width="740" height="440" fill="#fffef8" stroke="#d5d9cc"/><rect x="150" y="118" width="700" height="402" fill="none" stroke="#8a9481" stroke-width=".8"/><path d="M150 490h700M600 490v30M740 490v30M600 505h250" fill="none" stroke="#8a9481" stroke-width=".65"/><text x="165" y="508" fill="#64715b" font-size="10">MULTICAD / ${projects[state.project].name.toUpperCase()}</text><text x="610" y="500" fill="#64715b" font-size="8">PART FABRICATION</text><text x="610" y="516" fill="#64715b" font-size="8">REV ${projects[state.project].version} · SCALE ${state.drawingScale}</text><text x="750" y="500" fill="#64715b" font-size="8">A3 · FIRST ANGLE</text><text x="750" y="516" fill="#64715b" font-size="8">SHEET 01 / 03</text><g data-action="add-view" style="cursor:pointer"><rect x="232" y="178" width="247" height="118" rx="3" fill="none" stroke="#52634c" stroke-width="1.2"/><rect x="267" y="201" width="151" height="64" fill="none" stroke="#52634c" stroke-width="1"/>${[0,1,2].map(i=>`<circle cx="446" cy="${207+i*31}" r="6" fill="none" stroke="#52634c"/>`).join('')}<path d="M224 236h263M355 169v137" stroke="#9da793" stroke-width=".6" stroke-dasharray="10 3 2 3"/><text class="tiny" x="355" y="324" text-anchor="middle">FRONT</text>${state.dimensions?dimension(232,154,479,154,'480')+dimension(203,178,203,296,'230',true)+dimension(267,282,418,282,'294'):''}</g><g data-action="add-view" style="cursor:pointer"><rect x="560" y="178" width="125" height="118" fill="none" stroke="#52634c" stroke-width="1.2"/><path d="M560 190h125M560 284h125" stroke="#52634c"/><text class="tiny" x="622" y="324" text-anchor="middle">RIGHT</text>${state.dimensions?dimension(560,154,685,154,'280'):''}</g><g data-action="section-view" style="cursor:pointer"><path d="M235 375h240v12H247v53h-12Z" fill="url(#hatch)" stroke="#52634c" stroke-width="1"/><path d="M235 375v65M475 375v65" stroke="#7e8d72" stroke-dasharray="5 3"/><text class="tiny" x="355" y="463" text-anchor="middle">SECTION A–A · 1:2</text>${state.dimensions?dimension(494,375,494,440,'24',true):''}</g><g transform="translate(620 396)"><path d="m-35-29 70-18 50 25-70 20Z" fill="#ecefe4" stroke="#67765e" stroke-width=".9"/><path d="m-35-29 50 27v38l-50-27Z" fill="#f5f5ec" stroke="#67765e" stroke-width=".9"/><path d="m15-2 70-20v38L15 36Z" fill="#e4e9da" stroke="#67765e" stroke-width=".9"/><text class="tiny" x="20" y="66" text-anchor="middle">ISOMETRIC</text></g><text x="169" y="351" fill="#76826a" font-size="9">NOTES</text><text x="169" y="366" fill="#65755c" font-size="9">${esc(state.drawingNote.slice(0,55))}</text><text x="740" y="140" fill="#7a866f" font-size="8">ALL DIMENSIONS IN mm</text><path d="M495 174v132" stroke="#b57d5e" stroke-width=".9" stroke-dasharray="10 4 2 4"/><text x="491" y="169" fill="#b57d5e" font-size="10">A</text><text x="491" y="317" fill="#b57d5e" font-size="10">A</text></g></svg>`;}
function scene(){if(state.workspace==='sketch'&&state.view!=='3d')return sketchScene();if(state.workspace==='drawings'&&state.view!=='model')return drawingScene();if(state.workspace==='sheet'&&state.flat)return flatScene();if(state.workspace==='room'&&state.view==='plan')return roomScene();return isoScene();}
function manufacturing(){const tab=state.manufacturing||'parts';return `<section class="manufacturing" aria-label="Manufacturing schedules"><div class="manufacturing-head"><div class="row">${icon('list')}<strong>Manufacturing package</strong><span class="pill green">Linked to design</span></div><button class="icon-btn" data-action="close-manufacturing" aria-label="Close schedules">${icon('close')}</button></div><nav class="manufacturing-tabs">${[['parts','Parts & materials'],['cuts','Cut list'],['bends','Bends'],['welds','Weld sequence'],['files','Output files']].map(([id,v])=>`<button data-schedule="${id}" class="${tab===id?'active':''}">${v}</button>`).join('')}</nav><div class="manufacturing-body">${scheduleContent(tab)}</div></section>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((c,i)=>`<td class="${typeof c==='number'?'num':''}">${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function scheduleContent(tab){if(tab==='parts')return table(['Part','Material','Qty','Process'],projects[state.project].parts.map((name,i)=>[name,projects[state.project].materials[i]||'Mixed',i===1?2:1,projects[state.project].materials[i]?.includes('PETG')?'FDM print':projects[state.project].materials[i]?.includes('Birch')?'CNC panel':projects[state.project].materials[i]?.includes('5052')?'Cut & bend':name.includes('frame')?'Cut & weld':'Purchased / reference']));if(tab==='cuts')return table(['Part / member','Stock','Length','Width','Qty','Ends'],[['Top · Layer 1','Birch plywood · 18',1600,800,1,'Square'],['Top · Layer 2','Birch plywood · 18',1600,800,1,'Square'],['Frame · Long rail','SHS 30 × 30 × 2',1500,'—',4,'45° / 45°'],['Frame · Short rail','SHS 30 × 30 × 2',700,'—',4,'45° / 45°'],['Frame · Leg','SHS 30 × 30 × 2',670,'—',4,'90° / 90°']]);if(tab==='bends')return table(['ID','Angle','Direction','Inside R','Flange','Sequence'],[1,2,3,4].map(i=>['B'+i,'90°','Up',state.bendRadius+' mm','24 mm',i]));if(tab==='welds')return table(['Order','Joint','Weld','Length','Instruction'],[['1','W1A / W1B','Tack','10 mm','Opposite corners'],['2','W2A / W2B','Fillet · a3','30 mm','Alternate short sides'],['3','W3A / W3B','Fillet · a3','30 mm','Alternate long sides'],['4','Mounting plates','Fillet · a3','20 mm','Confirm hole alignment']]);return outputFiles();}
function outputFiles(){const p=projects[state.project],scope=state.exportScope==='selected'?state.selected:state.exportScope==='assembly'?'Current assembly':'Whole project';const base=state.exportScope==='selected'?state.selected.toLowerCase().replace(/[^a-z0-9]+/g,'-'):p.file;const suffix={STEP:'step',OBJ:'obj','3MF':'3mf',STL:'stl',GLB:'glb',DXF:'dxf',PDF:'pdf',CSV:'csv',SVG:'svg'};const list=state.modal==='export'?[[state.exportFormat,base+'.'+suffix[state.exportFormat],scope+' · '+(state.exportFormat==='DXF'?'1:1 contours with separate cut / bend layers':state.exportFormat==='PDF'?'Dimensioned drawing sheets':state.exportFormat==='GLB'?'Part hierarchy and appearance for Blender':'Selected output settings')]]:[['DXF',p.file+'-contours.dxf','Cut contours · 1:1'],['PDF',p.file+'-drawings.pdf','Projections, sections, fabrication notes'],['CSV',p.file+'-parts.csv','Part identities, materials, quantities'],['STEP',p.file+'.step','Assembly hierarchy'],['3MF','printed-parts.3mf','Print parts + optional design aids']];return list.map(([ext,name,sub])=>`<div class="output-row"><span class="output-icon">${ext}</span><div><strong>${esc(name)}</strong><small>${esc(sub)}</small></div><span class="spacer"></span><span class="pill">Preview</span></div>`).join('');}

const symbolList=[['cabinet','Workshop cabinet','Dynamic · W / H / D','wood'],['door','Single door','Dynamic · Width / height','door'],['laser','Laser cutter','Dynamic · Service envelope','cube'],['rail','Drawer rail · 400','Static · Purchased component','assembly'],['key','MX key guide','Dynamic · Rows / columns','grid'],['tube','SHS 30 × 30 × 2','Dynamic · Length / cut angle','weld']];
function symbolArt(id){if(id==='door')return `<svg viewBox="0 0 160 100"><path d="M45 89V12h63v77M48 89l44-10V19L48 12Z" fill="#d4bd91" stroke="#8c805f"/><path d="M81 49v8" stroke="#8c805f" stroke-width="2"/></svg>`;if(id==='rail')return `<svg viewBox="0 0 160 100"><path d="m30 70 80-38 13 9-80 38Z" fill="#b2beb0" stroke="#80907a"/><path d="m50 79 82-38 10 8-82 38Z" fill="#d3dbca" stroke="#80907a"/><circle cx="58" cy="61" r="2" fill="#72816b"/><circle cx="97" cy="42" r="2" fill="#72816b"/></svg>`;if(id==='key')return `<svg viewBox="0 0 160 100"><path d="m23 62 75-31 38 20-75 32Z" fill="#bbc8a8" stroke="#839876"/>${[0,1].map(r=>[0,1,2,3].map(c=>`<path d="m${35+c*16+r*13} ${60-c*7+r*8} 11-5 8 5-11 5Z" fill="#e9efdd" stroke="#8b9f7d"/>`).join('')).join('')}</svg>`;if(id==='tube')return `<svg viewBox="0 0 160 100"><path d="m28 70 82-45 22 14-82 45Z" fill="#9eaf9b" stroke="#61765d"/><path d="M28 70v-17l82-45v17M28 53l22 14v17" fill="#73896f" stroke="#61765d"/><path d="m33 60 12 8v9l-12-8Z" fill="#e9eddf" stroke="#61765d"/></svg>`;return `<svg viewBox="0 0 160 100"><path d="m48 26 51-13 26 17-51 15Z" fill="${id==='laser'?'#c7d5ca':'#d7c397'}" stroke="#8a987b"/><path d="M48 26v48l26 18V45Z" fill="${id==='laser'?'#8ea696':'#bea577'}" stroke="#8a987b"/><path d="m74 45 51-15v48L74 92Z" fill="${id==='laser'?'#afc2af':'#ceba8d'}" stroke="#8a987b"/><path d="m79 61 41-12m-41 27 41-12" stroke="#8a987b"/></svg>`;}
function projectArt(id){if(id==='makerspace')return `<svg viewBox="0 0 330 150"><path d="M58 28h214v96h-70m-36 0H58V28" fill="#e0e5d5" stroke="#89987a" stroke-width="5"/><path d="M166 124V89a36 36 0 0 1 36 35" fill="none" stroke="#acb59d"/><rect x="177" y="57" width="66" height="39" fill="#a5bcae" stroke="#74927e"/><rect x="82" y="103" width="102" height="12" fill="#caba95"/><rect x="69" y="42" width="18" height="49" fill="#caba95"/></svg>`;return `<svg viewBox="0 0 330 150"><g transform="translate(85 -1) scale(1.3)">${symbolArt(id==='case'?'cabinet':id==='console'?'key':'tube').replace(/<svg[^>]*>|<\/svg>/g,'')}</g></svg>`;}
function modalWrap(title,subtitle,body,footer='',cls='',tabs=''){return `<div class="modal-backdrop" data-backdrop><section class="modal ${cls}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></header>${tabs}<div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;}
function renderModal(){const m=state.modal;if(!m){overlays.innerHTML='';return;}let out='';if(m==='projects')out=modalWrap('Your projects','One model. Every material. Every manufacturing step.',`<div class="row spread" style="margin:1px 0 18px"><span class="eyebrow">Sample projects</span>${button('new-project','New project','plus','small')}</div><div class="project-grid">${Object.entries(projects).map(([id,p])=>`<button class="project-card" data-project="${id}"><div class="project-art">${projectArt(id)}</div><div class="project-info"><strong>${p.name}</strong><small>${p.sub} · Revision ${p.version}</small></div></button>`).join('')}</div>`,`${button('close-modal','Back to design')}`,'wide');
else if(m==='library')out=libraryModal();else if(m==='create-symbol')out=modalWrap('Create a parametric symbol','Package a part or an entire assembly for reuse.',`<div class="two-col"><div><label class="eyebrow" for="symbol-name">Symbol name</label><input class="full-input" id="symbol-name" value="${state.project==='case'?'Workshop cabinet':projects[state.project].name}" style="margin:9px 0 18px">${selectField('Content','symbolContent',['Selected part','Whole assembly'],'Whole assembly')}<div class="section-label">Behavior</div><label class="radio-card"><input type="radio" name="symbol-type" value="dynamic" checked><span>Dynamic symbol<small>Ask for exposed values when placing. Each instance can have its own dimensions.</small></span></label><label class="radio-card"><input type="radio" name="symbol-type" value="static"><span>Static symbol<small>Reuse a fixed design with independent placement and rotation.</small></span></label></div><div><div class="section-label" style="margin-top:0">Exposed parameters</div>${check('exposeWidth','Width · 600 mm',true)}${check('exposeHeight','Height · 720 mm',true)}${check('exposeDepth','Depth · 450 mm',true)}${check('exposeStock','Material thickness · 18 mm',true)}${check('exposeJoinery','Joint clearance · 0.15 mm',false)}${notice('Internal constraints stay in the definition. Only checked parameters appear during placement.','','lock')}${check('planSymbol','Include simplified 2D plan symbol',true)}</div></div>`,`${button('library','Back')}${button('save-symbol','Create symbol','library','primary')}`);
else if(m==='symbol-update')out=modalWrap('Review symbol update','Workshop cabinet · Library v1.2 → v1.3',`<div class="modal-callout">This project keeps its embedded definition until you accept an update. Instance dimensions are preserved where compatible.</div><div class="change-row"><span>Hinge mounting pattern</span><span>4 holes → 6 holes</span></div><div class="change-row"><span>Panel edge clearance</span><span>0.2 mm → 0.3 mm</span></div><div class="change-row"><span>Exposed width, height, depth</span><span style="color:var(--green)">Preserved</span></div><div class="change-row"><span>Affected instances in this project</span><span>2 cabinets</span></div>${notice('Review the changed mounting pattern before updating manufactured parts.','warning')}`,`${button('close-modal','Keep v1.2')}${button('accept-symbol-update','Update 2 instances','refresh','primary')}`,'narrow');
else if(m==='export')out=exportModal();else if(m==='tour')out=tourModal();else if(m==='parameters')out=modalWrap('Project parameters','Expressions connect dimensions across parts and workspaces.',table(['Name','Value / expression','Used by'],[['cabinet_width','600 mm','Carcass, drawers, top'],['stock_thickness',state.woodThickness+' mm','4 panels, 3 joints'],['drawer_width','cabinet_width − 2 × stock_thickness − rail_gap','Upper & lower drawers'],['rail_gap','12.7 mm','Drawer rail placement'],['panel_depth',state.depth+' mm','Front panel extrusion']])+`<div class="two-col" style="margin-top:18px"><div>${field('Cabinet width',state.libraryWidth,'libraryWidth')}${field('Stock thickness',state.woodThickness,'woodThickness')}</div><div>${notice('Expressions use explicit units. Updating a driving value rebuilds dependent features.','','link')}</div></div>`,`${button('close-modal','Close')}${button('apply-parameters','Apply parameters','check','primary')}`);
else if(m==='constraints')out=modalWrap('Sketch constraints','Master sketch · 23 constraints · 0 degrees of freedom',table(['Type','Geometry','Value','State'],[['Distance','Bottom edge','120 mm','Driving'],['Distance','Left edge','80 mm','Driving'],['Equal','Hole 1 ↔ Hole 2','—','Satisfied'],['Symmetric','Plate ↔ Vertical axis','—','Satisfied'],['Horizontal','Top & bottom edges','—','Satisfied'],['Tangent','Corner arcs','—','Satisfied']])+notice('When a new constraint conflicts, the affected geometry and conflicting constraints appear together.','','info'),`${button('constraint-conflict','Preview a conflict','alert')}${button('close-modal','Done','','primary')}`);
else if(m==='constraint-conflict')out=modalWrap('Two dimensions conflict','The sketch cannot be both 120 mm and 140 mm wide.',`<div class="reference-card"><strong>Conflicting constraints</strong><br>Width · 120 mm · Existing driving dimension<br>Distance 24 · 140 mm · Newly added</div>${notice('The last valid sketch is preserved. Choose how to resolve the new constraint.','warning')}<label class="radio-card"><input name="conflict" type="radio" checked><span>Replace the existing width<small>Use 140 mm as the driving dimension.</small></span></label><label class="radio-card"><input name="conflict" type="radio"><span>Make the new dimension a reference<small>Show a measured value without constraining the sketch.</small></span></label>`,`${button('close-modal','Cancel constraint')}${button('resolve-constraint','Resolve','check','primary')}`,'narrow');
else if(m==='repair')out=modalWrap('Repair a design reference','Mounting sketch · Source face no longer exists',`<div class="two-col"><div>${notice('The upstream cut removed the face used by this sketch. The last valid result remains visible.','warning','alert')}<div class="section-label">Previous reference</div><div class="reference-card">Front panel → Upper face<br>Used by Mounting sketch and 4 hole features.</div></div><div><div class="section-label" style="margin-top:0">Replacement</div><label class="radio-card"><input name="repair" type="radio" checked><span>Upper face of Front panel<small>Parallel plane · 2 mm lower · 4 dependent holes</small></span></label><label class="radio-card"><input name="repair" type="radio"><span>Create a datum plane<small>Maintain the sketch position independently of this face.</small></span></label>${check('repairDependents','Update dependent features together',true)}</div></div>`,`${button('close-modal','Keep unresolved')}${button('apply-repair','Preview & repair','link','primary')}`);
else if(m==='pcb')out=modalWrap('Import mechanical PCB references','Import geometry that connects electronics to the rest of your design.',`<div class="two-col"><div class="modal-callout"><div class="row">${icon('file')}<strong>control-board.kicad_pcb</strong><span class="pill green">Sample</span></div><p>Board outline · 440 × 210 mm<br>4 mounting holes · 24 switches · 4 encoders</p><p>References retain source identifiers for future updates.</p></div><div>${check('pcbOutline','Board outline & thickness',true)}${check('pcbHoles','Mounting holes',true)}${check('pcbComponents','Component positions & envelopes',true)}${check('pcbModels','Referenced STEP models',true)}${notice('1 external model is missing. Use its footprint envelope or select a replacement STEP file.','warning')}</div></div><div class="section-label">Derived geometry</div>${button('import-pcb-cutouts','Select components for panel cutouts','cut','small')}`,`${button('close-modal','Cancel')}${button('import-pcb','Import linked references','link','primary')}`);
else if(m==='sync'||m==='companion')out=companionModal(m);else if(m==='connections')out=connectionsModal();else if(m==='settings')out=settingsModal();else if(m==='commands')out=commandsModal();else if(m==='sweep')out=modalWrap('Check the movement range','Slider travel · 0–400 mm · Sampled positions',`<div class="modal-callout">The movement is checked at intervals. This is a sampled clearance check, not a guarantee of continuous collision-free motion.</div>${table(['Position','Result','Affected parts'],[['0–330 mm','Clear','—'],['340 mm','Interference','Handle ↔ adjacent door'],['350–400 mm','Interference','Handle ↔ adjacent door']])}${field('Sample interval',10,'sweepStep')}${check('stopAtCollision','Stop preview at first interference',true)}`,`${button('close-modal','Close')}${button('show-collision','Show first interference','eye','primary')}`,'narrow');
else if(m==='fixture')out=modalWrap('Fixture-table layout','Optional fabrication workspace · Sample positioning plan',table(['Fixture','Table coordinate','Height','Purpose'],[['Corner stop A','X 100 / Y 100','0 mm','Locate frame origin'],['Corner stop B','X 1,600 / Y 100','0 mm','Locate long rail'],['Clamp 1','X 500 / Y 120','30 mm','Hold tube flat'],['Clamp 2','X 1,200 / Y 120','30 mm','Hold tube flat']])+notice('Fixture locations are authored references. They do not calculate weld distortion or structural safety.','','grid'),`${button('close-modal','Close')}${button('export','Preview fixture drawing','drawing','primary')}`);
else if(m==='sequence')out=modalWrap('Weld sequence','Document the order, orientation, and fixture notes for the fabricator.',`<div id="weld-order">${['Tack opposite corners','Weld short-side pairs','Weld long-side pairs','Attach mounting plates'].map((v,i)=>`<div class="step-row"><span class="step-num">${i+1}</span><span>${v}</span><span class="spacer"></span><button class="icon-btn" data-reorder="${i}" aria-label="Move ${v} earlier">${icon('rotate')}</button></div>`).join('')}</div><div class="section-label">Sequence note</div><textarea class="full-input" rows="3">Confirm diagonals before full welds. Alternate opposite sides.</textarea>`,`${button('close-modal','Cancel')}${button('save-sequence','Save weld plan','check','primary')}`,'narrow');
else if(m==='appearance')out=modalWrap('Appearance & Blender handoff','Keep manufacturing material and rendering appearance connected.',`<div class="two-col"><div><div class="material"><span class="swatch"></span><span>Birch plywood<small>Manufacturing material</small></span></div>${field('Roughness',.65,'roughness','')}${field('Metallic',0,'metallic','')}${selectField('Color','appearanceColor',['Natural birch','Dark graphite','Brushed aluminium'],'Natural birch')}</div><div>${check('exportHierarchy','Preserve part names & hierarchy',true)}${check('exportMaterials','Include appearance materials',true)}${check('exportInstances','Keep repeated instances',true)}${notice('Export GLB to continue lighting, materials, and rendering in Blender.','','cube')}</div></div>`,`${button('close-modal','Close')}${button('blender-export','Preview GLB export','download','primary')}`);
else if(m==='health')out=modalWrap('Design health','Geometry, constraints, and references share one place for diagnostics.',table(['Check','Status','Detail'],[['Sketch constraints','Satisfied','23 constraints · 0 free dimensions'],['Solid validity','Valid','All sample solids closed'],['Source references',state.sketchIssue?'Needs repair':'Resolved',state.sketchIssue?'Mounting sketch source removed':'All links available'],['Drawing revision','Current','Matches design revision'],['Library definitions','Pinned','2 instances on v1.2']]),`${button('repair','Explore reference repair','link')}${button('close-modal','Done','','primary')}`);
else if(m==='new-project')out=modalWrap('New project','Start with a workflow. Add other disciplines whenever you need them.',`<label class="eyebrow" for="new-project-name">Project name</label><input id="new-project-name" class="full-input" value="Untitled project" style="margin:10px 0 20px"><div class="option-grid">${[['room','Room layout'],['model','Part design'],['assembly','Assembly'],['wood','Woodworking']].map(([id,v])=>`<button data-new-template="${id}">${icon(id==='model'?'cube':id)}${v}</button>`).join('')}</div>`,`${button('close-modal','Cancel')}`,'narrow');
else if(m==='annotation')out=modalWrap('Add a drawing note','Notes stay on the sheet; model dimensions remain associative.',`<label class="eyebrow" for="annotation-text">Text</label><textarea id="annotation-text" class="full-input" rows="4" style="margin-top:10px">${esc(state.drawingNote)}</textarea>${selectField('Style','noteStyle',['General note','Leader note','Weld note'],'General note')}`,`${button('close-modal','Cancel')}${button('add-annotation','Place note','text','primary')}`,'narrow');
else if(m==='add-view')out=modalWrap('Add drawing view','Choose a model view or derive a section and detail.',`<div class="option-grid">${['Front','Top','Right','Isometric','Section A–A','Detail B','Exploded assembly','Flat pattern'].map(v=>`<button data-add-view="${v}">${icon(v.includes('Section')?'section':'drawing')}${v}</button>`).join('')}</div>${selectField('View scale','drawingScale',['1:1','1:2','1:5','1:10'],state.drawingScale)}`,`${button('close-modal','Cancel')}`,'narrow');
else if(m==='dimension')out=modalWrap('Add associative dimension','Pick geometry in the view, then place the dimension.',`<div class="option-grid">${['Linear','Aligned','Angle','Diameter / radius','Hole callout','Ordinate'].map(v=>`<button data-dimtype="${v}">${icon('ruler')}${v}</button>`).join('')}</div>${check('dimensionDriving','Reference measurement on drawing',true)}${notice('Drawing dimensions measure the model. Edit the driving sketch or parameter to change the part.','','link')}`,`${button('close-modal','Cancel')}`,'narrow');
else if(m==='materials')out=modalWrap('Materials & stock','Manufacturing properties travel with each part.',table(['Material','Stock','Typical process'],[['Birch plywood · B/BB','18 mm sheet','Saw / CNC / laser'],['Steel · S235','SHS 30 × 30 × 2','Cut & weld'],['Aluminium · 5052','2 mm sheet','Laser & bend'],['PETG','FDM filament','3D print']])+notice('Grain, stock thickness, bend data, and rendering appearance are separate editable properties.','','layers'),`${button('close-modal','Close')}${button('apply-material','Assign to selection','check','primary')}`);
overlays.innerHTML=out;requestAnimationFrame(()=>{overlays.querySelector('input:not([type=checkbox]):not([type=radio]),textarea,button')?.focus({preventScroll:true});});}
function symbolFields(id){const custom=(state.customSymbols||[]).find(s=>s[0]===id);if(custom)return custom[2].startsWith('Static')?'<p class="muted">Fixed definition · No exposed parameters.</p>':custom[4].map(k=>field(k,k==='Width'?state.libraryWidth:k==='Height'?state.libraryHeight:k==='Depth'?state.libraryDepth:state.woodThickness,'library'+k.replaceAll(' ',''))).join('')||'<p class="muted">No parameters exposed.</p>';if(id==='tube')return field('Length',state.libraryLength||1000,'libraryLength')+field('End cut angle',state.libraryAngle||45,'libraryAngle','°');if(id==='key')return field('Rows',state.libraryRows||3,'libraryRows','')+field('Columns',state.libraryColumns||8,'libraryColumns','')+field('Key pitch',19.05,'libraryPitch');return field('Width',state.libraryWidth,'libraryWidth')+field('Height',state.libraryHeight,'libraryHeight')+(id==='door'?field('Thickness',40,'libraryDoorThickness'):field('Depth',state.libraryDepth,'libraryDepth'));}
const allSymbols=()=>[...symbolList,...(state.customSymbols||[])];
function libraryModal(){const found=allSymbols().filter(([id,name,type])=>(state.symbolFilter==='All'||type.startsWith(state.symbolFilter))&&name.toLowerCase().includes(state.symbolSearch.toLowerCase()));const sym=allSymbols().find(s=>s[0]===state.symbol)||symbolList[0];return modalWrap('Symbol library','Reusable parts and assemblies, with the right parameters exposed.',`<div class="filter-row"><input class="full-input" id="symbol-search" value="${esc(state.symbolSearch)}" placeholder="Search your library…" aria-label="Search symbols">${['All','Dynamic','Static'].map(v=>`<button class="chip ${state.symbolFilter===v?'active':''}" data-symbol-filter="${v}">${v}</button>`).join('')}</div><div class="modal-grid"><div class="library-grid">${found.map(([id,name,type])=>`<button class="symbol-card ${state.symbol===id?'active':''}" data-symbol="${id}"><div class="symbol-art">${symbolArt(id)}</div><div class="symbol-info"><strong>${esc(name)}</strong><small>${esc(type)}</small></div></button>`).join('')||'<p class="empty-state">No matching symbols.</p>'}</div><div class="symbol-form"><span class="eyebrow">${sym[2].split(' ·')[0]} symbol</span><h3>${esc(sym[1])}</h3><span class="pill">Definition v1.2 · Embedded on placement</span><div class="section-label">${sym[0]==='rail'?'Fixed dimensions':'Exposed parameters'}</div>${sym[0]==='rail'?`<div class="field"><span>Length</span><span class="mono">400 mm</span></div><div class="field"><span>Travel</span><span class="mono">400 mm</span></div><div class="field"><span>Mounting holes</span><span>4 references</span></div>`:symbolFields(sym[0])}${check('symbolLinked','Keep link to definition version',true)}${check('symbolPlan','Use simplified plan representation',true)}${notice('Existing instances update only when you accept a new definition version.','','lock')}</div></div>`,`${button('create-symbol','Create symbol','plus')}${button('place-symbol','Place in project','plus','primary')}`,'wide');}
function exportModal(){const formats=state.workspace==='drawings'?['PDF','DXF','SVG','CSV']:['STEP','OBJ','3MF','STL','GLB','DXF','PDF','CSV'];if(state.exportStage===1)return modalWrap('Export package preview','Review the files and the scope before a manufacturing handoff.',`<div class="modal-callout">UX prototype: these are example output names and options. No CAD or manufacturing files are generated.</div>${outputFiles()}`,`${button('export-back','Back')}${button('finish-export','Done','check','primary')}`);return modalWrap('Export your design','Select exactly what leaves the project.',`<div class="two-col"><div><div class="section-label" style="margin-top:0">Scope</div><label class="radio-card"><input type="radio" name="export-scope" value="selected" ${state.exportScope==='selected'?'checked':''}><span>Selected parts<small>${esc(state.selected)} · 1 part</small></span></label><label class="radio-card"><input type="radio" name="export-scope" value="assembly" ${state.exportScope==='assembly'?'checked':''}><span>Current assembly<small>All contained parts, with placements</small></span></label><label class="radio-card"><input type="radio" name="export-scope" value="project" ${state.exportScope==='project'?'checked':''}><span>Whole project<small>Assemblies, drawing sheets, and schedules</small></span></label><div class="section-label">Format</div><div class="format-grid">${formats.map(v=>`<button class="format ${state.exportFormat===v?'active':''}" data-format="${v}">${v}<small>${{STEP:'Solid geometry',OBJ:'Mesh', '3MF':'Print package',STL:'Print mesh',GLB:'Blender / render',DXF:'2D manufacturing',PDF:'Drawing sheets',CSV:'Parts & cut lists',SVG:'Vector drawing'}[v]}</small></button>`).join('')}</div></div><div><div class="section-label" style="margin-top:0">Output settings</div>${selectField('Units','exportUnits',['Millimetres','Inches'],'Millimetres')}${selectField('Mesh quality','meshQuality',['Fine','Balanced','Coarse'],'Balanced')}${check('exportNames','Preserve names & assembly hierarchy',true)}${check('exportAids','Include removable print aids',state.workspace==='print')}${check('exportBends','Separate cut / bend / drill layers',true)}${check('exportLatest','Require up-to-date drawings',true)}${notice(state.exportFormat==='GLB'?'GLB carries part hierarchy and appearance for your Blender workflow.':state.exportFormat==='DXF'?'Manufacturing contours export at 1:1. Drawing sheets retain their selected sheet scale.':'STEP preserves solid geometry. Mesh formats use a separate tessellation quality.','','info')}</div></div>`,`${button('close-modal','Cancel')}${button('preview-export','Preview export package','download','primary')}`);}
function tourModal(){const items=[['makerspace','room','Plan a makerspace','Draw walls and openings, position equipment, inspect service clearances.'],['console','sketch','One sketch, several parts','Select independent profiles, extrude them, and retain shared parameters.'],['console','model','Model with intent','Face sketches, primitives, Booleans, holes, and feature editing.'],['table','wood','Connect wooden panels','Lamination, grain, finger joints, miters, and both butt-joint arrangements.'],['table','weld','Fabricate a tube frame','Profiles, end cuts, weld positions, cut lists, and weld order.'],['console','sheet','Fold and unfold','Bends, reliefs, cutouts, developed contours, and bend schedules.'],['case','assembly','Check moving assemblies','Drawer extension, hinge position, clearances, and interference.'],['case','print','Prepare for FDM','Orientation, fits, breakaway tabs, and removable design aids.'],['console','drawings','Make manufacturing drawings','Views, sections, dimensions, annotations, PDF and DXF handoff.']];return modalWrap('Explore the complete workflow','Every scene is interactive sample data. Geometry, checks, and exports are simulated.',`<div class="tour-grid">${items.map(([p,w,title,desc])=>`<button class="tour-card" data-tour="${p}:${w}">${icon(w==='model'?'cube':w)}<strong>${title}</strong><p>${desc}</p></button>`).join('')}</div><div class="section-label">Shared features</div><div class="filter-row" style="flex-wrap:wrap">${button('library','Parametric symbols','library','small')}${button('create-symbol','Author a symbol','plus','small')}${button('symbol-update','Review library updates','refresh','small')}${button('pcb','Import KiCad / DXF / STEP','file','small')}${button('repair','Repair references','link','small')}${button('ai','AI / MCP review','spark','small')}${button('companion','Site companion','phone','small')}${button('export','Export packages','download','small')}</div>`,`${button('close-modal','Back to design','','primary')}`,'wide');}
function companionModal(kind){return modalWrap(kind==='sync'?'Project revisions & site access':'On-site companion', 'Later-phase workflow · View, measure, and annotate published revisions.',`<div class="two-col"><div><div class="section-label" style="margin-top:0">Revision publishing</div><div class="change-row"><span>Desktop working revision</span><span>Revision ${state.revision}</span></div><div class="change-row"><span>Published revision</span><span>${state.revision>4?'Revision '+state.revision:'Revision 3'}</span></div>${button('publish','Publish current revision','cloud','small','style="margin-top:15px"')}<div class="section-label">Site notes</div><div class="notes-list"><p><strong>Door opening confirmed</strong><br>Actual clear width is 1,080 mm.<br><span class="muted">Entry door · Revision 3</span></p>${state.notes.map(n=>`<p><strong>${esc(n)}</strong><br><span class="muted">Laser cutter · Revision ${state.revision}</span></p>`).join('')}</div>${notice('Notes stay anchored to a revision and part. Conflicting desktop edits remain separate revisions.','','branch')}</div><div class="phone"><div class="phone-top">${projects[state.project].name}<small>Published revision ${state.revision>4?state.revision:3} · View only</small></div><div class="phone-scene">${projectArt(state.project)}</div><div class="phone-tools"><button data-action="site-measure">${icon('ruler')}Measure</button><button data-action="site-section">${icon('section')}Section</button><button data-action="site-note">${icon('note')}Note</button></div><div class="phone-note" id="phone-result"><strong>${state.measure?'Clearance · 650 mm':'Entry door · Site note'}</strong>${state.measure?'Measurement tied to the published revision.':'Door opening confirmed on site.'}<input class="full-input" id="site-note" placeholder="Add an on-site note…"><button class="btn small" data-action="save-site-note" style="margin-top:8px">Add note</button></div></div></div>`,`${button('close-modal','Close')}`);}
function connectionsModal(){return modalWrap('AI & MCP connections','Local application control, with inspectable changes and shared undo.',`<div class="setting-row"><div><strong>Enable local MCP access</strong><small>Allow configured clients to connect on this computer.</small></div><input type="checkbox" class="toggle" data-toggle="mcp" ${state.mcp?'checked':''} aria-label="Enable local MCP access"></div><div class="section-label">Permissions for connected assistants</div>${check('mcpRead','Inspect models, parameters, and measurements',true)}${check('mcpPreview','Create operation previews',true)}${check('mcpEdit','Apply reviewed changes',true)}${check('mcpExport','Export to approved folders',false)}<div class="section-label">Change handling</div>${selectField('Default','aiReview',['Review before applying','Allow trusted session changes'],'Review before applying')}${notice('Tools address parts and geometry directly. A group of edits is one transaction, visible in design history.','','link')}<div class="setting-row"><div><strong>Remote connections</strong><small>Separate configuration and authentication required.</small></div><input type="checkbox" class="toggle" aria-label="Remote connections"></div>`,`${button('close-modal','Done','','primary')}`,'narrow');}
function settingsModal(){return modalWrap('Application settings','A small, predictable working environment.',`${selectField('Default units','units',['Millimetres','Inches'],'Millimetres')}${selectField('Navigation','navigation',['CAD · Middle mouse orbit','Trackpad · Two-finger pan','Blender style'],'CAD · Middle mouse orbit')}<div class="field"><label>Appearance</label><span>Workshop light</span></div><div class="setting-row"><div><strong>Adaptive viewport detail</strong><small>Use lighter display meshes while navigating.</small></div><input type="checkbox" class="toggle" checked aria-label="Adaptive viewport detail"></div><div class="setting-row"><div><strong>Render on change</strong><small>Keep the viewport idle when nothing is changing.</small></div><input type="checkbox" class="toggle" checked aria-label="Render on change"></div><div class="setting-row"><div><strong>Auto-recovery snapshots</strong><small>Keep local recoverable design checkpoints.</small></div><input type="checkbox" class="toggle" checked aria-label="Auto-recovery snapshots"></div><button class="list-action" data-action="connections">AI & MCP access${icon('chevron')}</button>`,`${button('close-modal','Done','','primary')}`,'narrow');}
function commandsModal(){return modalWrap('Find a tool','Search actions across all workspaces.','<input class="command-input" id="command-search" placeholder="What do you want to do?" aria-label="Find a tool"><div id="command-results">'+commandResults('')+'</div>','','narrow');}
function commandResults(q){const commands=[['extrude','Extrude selected profiles','extrude','Model'],['joint','Connect panels with a joint','joint','Wood'],['holes','Transfer mounting holes','hole','Model'],['library','Place a parametric symbol','library','Library'],['flat','Show flat pattern','unfold','Sheet metal'],['motion','Adjust assembly position','sliders','Assembly'],['parameters','Edit project parameters','sliders','Project'],['repair','Repair a geometry reference','link','Project'],['export','Export selected parts','download','Project'],['annotation','Add drawing note','text','Drawings']];return commands.filter(c=>c[1].toLowerCase().includes(q.toLowerCase())).map(([id,label,i,space])=>`<button class="command-result" data-command="${id}">${icon(i)}${label}<small>${space}</small></button>`).join('')||'<p class="empty-state">No matching tools.</p>';}

function startOperation(kind,label,opts={}){state.modal=null;state.inspector='properties';state.operation={kind,label,...opts};if(kind==='extrude'){state.workspace='sketch';state.view='sketch';}if(kind==='joint'){state.workspace='wood';state.view='3d';}if(kind==='bend'){state.workspace='sheet';state.view='3d';}if(kind==='relationship')state.workspace='assembly';render();}
const operations={wall:['Draw a wall','room'],door:['Place a door','door'],window:['Place a window','window'],level:['Level & pedestal','plane'],revolve:['Revolve profile','rotate'],primitive:['Add a primitive','cube'],move:['Move & align','move'],panel:['Create a panel','wood'],laminate:['Laminate panels','layers'],profile:['Frame stock profile','weld'],cope:['Trim / cope member','cut'],'frame-path':['Draw a frame path','line'],'weld-joint':['Define a weld joint','bolt'],orientation:['Set print orientation','rotate'],clearance:['Fit clearance','ruler'],'base-sheet':['Create base sheet','sheet'],cutout:['Create a cutout','cut'],line:['Draw a line','line'],rectangle:['Draw a rectangle','rect'],circle:['Circle / arc','circle'],spline:['Draw a spline','sketch'],trim:['Trim / extend','cut'],'transform-sketch':['Transform sketch geometry','rotate'],'new-part':['Add a part','cube'],features:['Modeling features','sliders']};
function act(action){const w=state.workspace;
if(['projects','library','create-symbol','symbol-update','export','tour','parameters','constraints','constraint-conflict','repair','sync','companion','connections','settings','commands','sweep','fixture','sequence','appearance','health','new-project','annotation','add-view','materials'].includes(action)){state.modal=action;if(action==='export'){state.exportStage=0;state.exportFormat=w==='drawings'?'PDF':w==='print'?'3MF':'STEP';}if(action==='library')state.symbolSearch='';renderModal();return;}
if(action==='close-modal'){state.modal=null;renderModal();return;}
if(action==='undo'){if(undoStack.length){redoStack.push(clone(state));state=undoStack.pop();state.modal=null;render();toast('Last change undone.');}return;}
if(action==='redo'){if(redoStack.length){undoStack.push(clone(state));state=redoStack.pop();render();toast('Change restored.');}return;}
if(action==='save'){state.saved=true;try{localStorage.setItem('multicad-ux-sample',JSON.stringify(state));}catch{}render();toast('Sample project state saved in this browser.');return;}
if(action==='ai'){state.modal=null;state.inspector=state.inspector==='ai'?'properties':'ai';state.operation=null;render();return;}
if(action==='cancel-op'){state.operation=null;render();return;}
if(action==='apply-op'){const op=state.operation;if(!op)return;commit(op.label,()=>{if(op.kind==='extrude'){state.placed.push('Extruded plate','Mounting bracket');state.workspace='model';state.view='3d';state.selected='Extruded plate';}else if(['wall','door','window'].includes(op.kind)){state.placed.push(op.kind==='door'?'New door':op.kind==='window'?'New window':'New wall');}else if(['support','bridge'].includes(op.kind))state.supports++;else if(op.kind==='relationship'){state.workspace='assembly';}else if(op.kind==='holes'){state.selected='Front panel';}});return;}
if(action==='extrude'){startOperation('extrude','Extrude profiles',{icon:'extrude',description:'Choose source regions and the result you want. The same sketch can drive several parts.'});return;}
if(action==='new-sketch'){state.workspace='sketch';state.view='sketch';state.operation=null;state.selected='Master sketch';render();toast('Sketch on the selected face · Linked to parent geometry.');return;}
if(action==='joint'){startOperation('joint','Connect panels',{icon:'joint',description:'Define one connection that generates the matching cuts on both panels.'});return;}
if(action==='boolean'){startOperation('boolean','Boolean operation',{icon:'union'});return;}
if(action==='holes'||action==='import-pcb-cutouts'){startOperation('holes',action==='holes'?'Transfer mounting holes':'Derive panel cutouts',{icon:'hole'});return;}
if(action==='pcb'){state.modal='pcb';renderModal();return;}
if(action==='import-pcb'){commit('Import linked PCB references',()=>{state.modal=null;state.project='console';state.workspace='model';state.view='3d';state.selected='Front panel';});return;}
if(action==='bend'){startOperation('bend','Flange / bend',{icon:'bend'});return;}
if(action==='flat'||action==='folded'){state.workspace='sheet';state.flat=action==='flat';state.view=state.flat?'plan':'3d';state.modal=null;render();return;}
if(action==='support'||action==='bridge'){state.workspace='print';startOperation(action,action==='support'?'Breakaway tab':'Thin sacrificial bridge',{icon:action==='support'?'pin':'joint'});return;}
if(action==='relationship'){startOperation('relationship','Assembly relationship',{icon:'link'});return;}
if(action==='motion'){state.workspace='assembly';state.operation=null;state.modal=null;render();return;}
if(action==='interference'){state.workspace='assembly';state.operation=null;render();toast((state.project==='console'?state.hinge>82:state.drawers>335)?'Sample check: interference highlighted at this position.':'Sample check: no interference at this position.');return;}
if(action==='show-collision'){state.modal=null;state.drawers=340;state.hinge=90;state.workspace='assembly';render();return;}
if(action==='explode'){state.explode=state.explode?0:90;render();return;}
if(action==='fitcheck'){state.clearance=true;render();toast(roomGap()>=600?`Sample layout: ${roomGap()} mm front clearance · Requirement 600 mm.`:'Sample layout: service envelope intersects the bench.');return;}
if(action==='measure'){state.measure=!state.measure;render();return;}
if(action==='section'){state.section=!state.section;render();return;}
if(action==='toggle-grid'){state.grid=!state.grid;render();return;}
if(action==='cycle-view'){state.view=state.view==='3d'?'plan':'3d';if(state.workspace==='sheet')state.flat=state.view==='plan';render();return;}
if(action==='fit-view'){yaw=-.62;document.getElementById('scene').style.transform='';renderScene();toast('View fitted to project.');return;}
if(action==='zoom-in'||action==='zoom-out'){const el=document.getElementById('scene');const scale=Number(el.dataset.zoom||1)+(action==='zoom-in'?.15:-.15);el.dataset.zoom=Math.max(.6,Math.min(1.7,scale));el.style.transform=`scale(${el.dataset.zoom})`;return;}
if(['manufacturing','cutlist','bends'].includes(action)){state.manufacturing=action==='cutlist'?'cuts':action==='bends'?'bends':'parts';state.modal=null;render();return;}
if(action==='close-manufacturing'){state.manufacturing=null;render();return;}
if(action==='drawing-dimension'||action==='dimension'){state.modal='dimension';renderModal();return;}
if(action==='section-view'){state.workspace='drawings';state.view='sheet';state.modal='add-view';render();return;}
if(action==='place-symbol'){const sym=allSymbols().find(s=>s[0]===state.symbol);commit('Place '+sym[1],()=>{state.placed.push(sym[1]+' · '+state.libraryWidth+' mm');state.selected=state.placed.at(-1);state.modal=null;});return;}
if(action==='save-symbol'){const name=document.getElementById('symbol-name')?.value||'New symbol';const dynamic=document.querySelector('input[name="symbol-type"]:checked')?.value!=='static';state.customSymbols||=[];const id='custom-'+(state.customSymbols.length+1);const exposed=['Width','Height','Depth','Stock'].filter(k=>state['expose'+k]!==false);state.customSymbols.push([id,name,(dynamic?'Dynamic':'Static')+' · Project definition','wood',exposed]);state.symbol=id;state.symbolFilter='All';state.symbolSearch='';state.modal='library';renderModal();toast(name+' · Symbol added to the prototype library.');return;}
if(action==='accept-symbol-update'){commit('Update symbol definition to v1.3',()=>{state.modal=null;state.symbolUpdate=true;});return;}
if(action==='apply-parameters'){commit('Update project parameters',()=>state.modal=null);return;}
if(action==='constraint-conflict'){state.modal='constraint-conflict';renderModal();return;}
if(action==='resolve-constraint'){commit('Resolve sketch constraint',()=>{state.sketchWidth=140;state.modal=null;});return;}
if(action==='apply-repair'){commit('Repair mounting sketch reference',()=>{state.sketchIssue=false;state.modal=null;});return;}
if(action==='preview-export'){state.exportStage=1;renderModal();return;}
if(action==='export-back'){state.exportStage=0;renderModal();return;}
if(action==='finish-export'){state.modal=null;renderModal();toast('Export workflow reviewed. Prototype does not generate CAD files.');return;}
if(action==='blender-export'){state.exportFormat='GLB';state.modal='export';state.exportStage=0;renderModal();return;}
if(action==='ai-send'){state.aiPrompt=document.getElementById('ai-prompt')?.value||'Add four mounting holes to the selected panel, linked to the PCB.';state.aiDraft=true;state.aiApplied=false;state.operation=null;render();return;}
if(action==='ai-apply'){commit(state.aiPrompt.includes('cabinet')?'AI · Resize cabinet':state.aiPrompt.includes('drawing')?'AI · Manufacturing drawing':'AI · Linked mounting holes',()=>{state.aiDraft=false;state.aiApplied=true;if(state.aiPrompt.includes('cabinet'))state.libraryWidth=700;if(state.aiPrompt.includes('drawing')){state.workspace='drawings';state.view='sheet';}});return;}
if(action==='ai-discard'){state.aiDraft=false;state.aiApplied=false;render();return;}
if(action==='publish'){state.revision++;renderModal();toast('Published revision preview updated. No server connection is made.');return;}
if(action==='site-measure'){state.measure=true;renderModal();return;}
if(action==='site-note'){document.getElementById('site-note')?.focus();return;}
if(action==='site-section'){const el=document.querySelector('.phone-scene');el.style.clipPath=el.style.clipPath?'':'inset(0 30% 0 0)';toast('Section preview enabled.');return;}
if(action==='save-site-note'){const value=document.getElementById('site-note')?.value.trim();if(value){state.notes.push(value);renderModal();toast('Site note added to sample revision.');}return;}
if(action==='add-annotation'){const value=document.getElementById('annotation-text')?.value;commit('Drawing note',()=>{state.drawingNote=value;state.modal=null;state.workspace='drawings';});return;}
if(action==='save-sequence'){commit('Weld sequence',()=>state.modal=null);return;}
if(action==='apply-material'){commit('Assign material',()=>state.modal=null);return;}
if(action==='material'){state.modal='materials';renderModal();return;}
if(action==='edit-selection'){startOperation('edit','Edit '+state.selected,{icon:'sliders'});return;}
if(action==='planes'){startOperation('datum','Construction plane',{icon:'plane'});return;}
if(action==='history-start'){toast('Origin and initial construction geometry selected.');return;}
if(operations[action]){const [label,i]=operations[action];startOperation(action,label,{icon:i});return;}}
app.addEventListener('click',e=>handleClick(e));overlays.addEventListener('click',e=>handleClick(e));
function handleClick(e){const el=e.target.closest('button,[data-eye],[data-part],[data-profile],[data-action]');if(!el)return;if(el.dataset.eye){e.stopPropagation();const n=el.dataset.eye;state.hidden=state.hidden.includes(n)?state.hidden.filter(v=>v!==n):[...state.hidden,n];render();return;}if(el.dataset.action){act(el.dataset.action);return;}if(el.dataset.space){state.workspace=el.dataset.space;state.operation=null;state.inspector='properties';state.view=state.workspace==='room'?'plan':state.workspace==='sketch'?'sketch':state.workspace==='drawings'?'sheet':'3d';render();return;}if(el.dataset.part){state.selected=el.dataset.part;state.inspector='properties';render();return;}if(el.dataset.view){if(state.workspace==='sheet')state.flat=el.dataset.view==='plan';state.view=el.dataset.view==='sheet'?'sheet':el.dataset.view==='sketch'?'sketch':el.dataset.view==='3d'?'3d':el.dataset.view;render();return;}if(el.dataset.inspector){state.inspector=el.dataset.inspector;state.operation=null;render();return;}if(el.dataset.project){go(el.dataset.project);return;}if(el.dataset.tour){const [p,w]=el.dataset.tour.split(':');go(p,w);return;}if(el.dataset.symbol){state.symbol=el.dataset.symbol;renderModal();return;}if(el.dataset.symbolFilter){state.symbolFilter=el.dataset.symbolFilter;renderModal();return;}if(el.dataset.profile!==undefined){const i=Number(el.dataset.profile);state.profiles=state.profiles.includes(i)?state.profiles.filter(v=>v!==i):[...state.profiles,i];render();return;}if(el.dataset.joint){state.joint=el.dataset.joint;render();return;}if(el.dataset.boolean){state.operation.result=el.dataset.boolean;render();return;}if(el.dataset.format){state.exportFormat=el.dataset.format;renderModal();return;}if(el.dataset.schedule){state.manufacturing=el.dataset.schedule;render();return;}if(el.dataset.pose!==undefined){state[state.project==='console'?'hinge':'drawers']=Number(el.dataset.pose);render();return;}if(el.dataset.aiExample){if(el.dataset.aiExample.includes('PCB'))go('console','model');if(el.dataset.aiExample.includes('cabinet'))go('case','assembly');state.inspector='ai';state.aiPrompt=el.dataset.aiExample;state.aiDraft=true;state.aiApplied=false;render();return;}if(el.dataset.command){state.modal=null;act(el.dataset.command);return;}if(el.dataset.feature){startOperation('shape-feature',el.dataset.feature,{icon:'cube'});return;}if(el.dataset.history!==undefined){const name=state.history[Number(el.dataset.history)];startOperation('history','Edit '+name,{icon:'sliders',description:'Editing an earlier feature updates its downstream references and manufacturing output.'});return;}if(el.dataset.newTemplate){state.modal=null;state.workspace=el.dataset.newTemplate;state.view=state.workspace==='room'?'plan':'3d';render();toast('New-project flow preview · Sample geometry retained.');return;}if(el.dataset.addView){commit('Drawing view · '+el.dataset.addView,()=>{state.modal=null;state.workspace='drawings';});return;}if(el.dataset.dimtype){commit('Dimension · '+el.dataset.dimtype,()=>{state.modal=null;state.dimensions=true;});return;}if(el.dataset.reorder!==undefined){const row=el.closest('.step-row'),prev=row.previousElementSibling;if(prev)row.parentNode.insertBefore(row,prev);return;}}
function handleInput(e){const el=e.target;if(el.dataset.range){const key=el.dataset.range;state[key]=Number(el.value);renderScene();const value=document.getElementById('motion-value');if(value)value.textContent=state.project==='console'?state.hinge+'°':state.drawers+' mm';const n=document.getElementById('motion-notice');if(n)n.innerHTML=motionNotice();return;}if(el.id==='command-search'){document.getElementById('command-results').innerHTML=commandResults(el.value);return;}if(el.id==='symbol-search'){state.symbolSearch=el.value;const start=el.selectionStart;renderModal();const next=document.getElementById('symbol-search');next?.focus();next?.setSelectionRange(start,start);return;}if(el.dataset.treeSearch!==undefined){for(const row of app.querySelectorAll('.tree-item'))row.style.display=row.textContent.toLowerCase().includes(el.value.toLowerCase())?'':'none';return;}if(el.dataset.note!==undefined){state.drawingNote=el.value;renderScene();return;}}
app.addEventListener('input',e=>handleInput(e));overlays.addEventListener('input',e=>handleInput(e));
function handleChange(e){const el=e.target;if(el.dataset.field){const v=Number(el.value);if(!Number.isFinite(v))return;const key=el.dataset.field;state[key]=v;if(key==='roomX')state.room.laser.x=170+v/10;if(key==='roomY')state.room.laser.y=110+v/10;renderScene();if(key==='fingers'||key==='depth')render();return;}if(el.dataset.select){state[el.dataset.select]=el.value;if(el.dataset.select==='extrudeResult'&&state.operation)state.operation.result=el.value;renderScene();return;}if(el.dataset.toggle){const key=el.dataset.toggle;if(key.startsWith('profile-')){const n=Number(key.slice(8));state.profiles=el.checked?[...new Set([...state.profiles,n])]:state.profiles.filter(i=>i!==n);}else if(key==='showDims')state.dimensions=el.checked;else state[key]=el.checked;renderScene();return;}if(el.name==='export-scope')state.exportScope=el.value;}
app.addEventListener('change',e=>handleChange(e));overlays.addEventListener('change',e=>handleChange(e));
document.addEventListener('keydown',e=>keyboardWorkflow(e));
overlays.addEventListener('click',e=>{if(e.target.matches('[data-backdrop]')){state.modal=null;renderModal();}});
function renderScene(){const el=document.getElementById('scene');if(el)el.innerHTML=scene();}
let drag=null;
function bindCanvas(){const el=document.getElementById('scene');el.addEventListener('pointerdown',e=>{if(e.button!==0&&e.button!==1)return;const svg=el.querySelector('svg');const target=e.target.closest('[data-drag]');if(target){const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());drag={kind:'equipment',start:p,pos:{...state.room.laser},el};el.setPointerCapture(e.pointerId);e.preventDefault();}else if(state.view==='3d'&& !e.target.closest('[data-part]')){drag={kind:'orbit',startX:e.clientX,yaw,el};el.setPointerCapture(e.pointerId);}});el.addEventListener('pointermove',e=>{if(!drag)return;if(drag.kind==='equipment'){const svg=el.querySelector('svg');const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());state.room.laser.x=Math.max(285,Math.min(580,drag.pos.x+p.x-drag.start.x));state.room.laser.y=Math.max(190,Math.min(370,drag.pos.y+p.y-drag.start.y));renderScene();}else{yaw=drag.yaw+(e.clientX-drag.startX)*.006;renderScene();}});el.addEventListener('pointerup',()=>{if(drag){if(drag.kind==='equipment'){state.saved=false;state.changes++;}drag=null;render();}});el.addEventListener('pointercancel',()=>drag=null);el.addEventListener('wheel',e=>{e.preventDefault();const scale=Math.max(.65,Math.min(1.7,Number(el.dataset.zoom||1)+(e.deltaY<0?.03:-.03)));el.dataset.zoom=scale;el.style.transform=`scale(${scale})`;},{passive:false});}
